insert into public.sources (id, author, title_fr, title_original, year) values
  ('S01', 'Napoleon Hill', 'Réfléchissez et devenez riche', 'Think and Grow Rich', 1937),
  ('S02', 'Robert Kiyosaki', 'Père riche, père pauvre', 'Rich Dad Poor Dad', 1997),
  ('S03', 'Rhonda Byrne', 'Le Secret', 'The Secret', 2006),
  ('S04', 'James Clear', 'Un rien peut tout changer', 'Atomic Habits', 2018),
  ('S05', 'Stephen R. Covey', 'Les 7 habitudes de ceux qui réalisent tout ce qu''ils entreprennent', 'The 7 Habits of Highly Effective People', 1989),
  ('S06', 'Dale Carnegie', 'Comment se faire des amis', 'How to Win Friends and Influence People', 1936),
  ('S07', 'George S. Clason', 'L''homme le plus riche de Babylone', 'The Richest Man in Babylon', 1926),
  ('S08', 'Gabriele Oettingen', 'Méthode WOOP (contraste mental)', 'Rethinking Positive Thinking', 2014),
  ('S09', 'Cal Newport', 'Deep Work', 'Deep Work', 2016),
  ('S10', 'Hal Elrod', 'Miracle Morning', 'The Miracle Morning', 2012),
  ('S11', 'Carol S. Dweck', 'Changer d''état d''esprit', 'Mindset', 2006),
  ('S12', 'Charles Duhigg', 'Le pouvoir des habitudes', 'The Power of Habit', 2012),
  ('S13', 'Brian Tracy', 'Avalez le crapaud !', 'Eat That Frog!', 2001),
  ('S14', 'Morgan Housel', 'La psychologie de l''argent', 'The Psychology of Money', 2020),
  ('S15', 'David Allen', 'S''organiser pour réussir', 'Getting Things Done', 2001);
insert into public.principles (id, domain, title_fr, summary_fr, title_en, summary_en, status) values
  ('P001', 'clarity_goals', 'Désir ardent et précis', 'Un objectif flou ne mobilise rien : il doit être précis, chiffré et vivement désiré.', 'Burning, definite desire', 'A vague goal mobilises nothing: it must be precise, quantified and strongly desired.', 'published'),
  ('P002', 'clarity_goals', 'Objectif écrit, chiffré et daté', 'Écrire son objectif avec un montant, une échéance et ce que l''on donnera en échange le rend concret.', 'Written, quantified, dated goal', 'Writing down the goal with an amount, a deadline and what you will give in return makes it concrete.', 'published'),
  ('P003', 'clarity_goals', 'Plan d''action immédiat', 'Un objectif sans plan reste un souhait : on définit les premières actions et on démarre tout de suite, même imparfaitement.', 'Immediate action plan', 'A goal without a plan is a wish: define the first actions and start right away, even imperfectly.', 'published'),
  ('P004', 'clarity_goals', 'Commencer avec la fin en tête', 'Clarifier ce que l''on veut avoir accompli à long terme pour orienter chaque décision du quotidien.', 'Begin with the end in mind', 'Clarify what you want to have achieved in the long run so it guides every daily decision.', 'published'),
  ('P005', 'clarity_goals', 'Mission personnelle', 'Rédiger ses valeurs et sa raison d''être donne une boussole pour arbitrer.', 'Personal mission statement', 'Writing down your values and purpose gives you a compass for trade-offs.', 'published'),
  ('P006', 'clarity_goals', 'Le « pourquoi » profond', 'Relier l''objectif à une raison personnelle forte entretient la motivation les jours difficiles.', 'Your deep why', 'Tying the goal to a strong personal reason keeps motivation alive on hard days.', 'published'),
  ('P007', 'clarity_goals', 'Contraste mental (WOOP)', 'Imaginer le résultat, puis l''obstacle intérieur principal et la réponse prévue, augmente le passage à l''action.', 'Mental contrasting (WOOP)', 'Picturing the outcome, then the main inner obstacle and a planned response, increases follow-through.', 'published'),
  ('P008', 'clarity_goals', 'Intention de mise en œuvre', 'Formuler « si situation X, alors je fais Y » rend l''action presque automatique.', 'Implementation intentions', 'Phrasing plans as “if situation X, then I do Y” makes action almost automatic.', 'published'),
  ('P009', 'clarity_goals', 'Visualisation suivie d''un plan', 'Se représenter le résultat aide à clarifier ce que l''on veut ; seule, elle peut démobiliser, elle doit donc déboucher sur un plan.', 'Visualisation followed by a plan', 'Picturing the result clarifies what you want; on its own it can sap energy, so it must lead to a plan.', 'published'),
  ('P010', 'clarity_goals', 'La grenouille d''abord', 'Faire en premier la tâche la plus importante, surtout si on a envie de la repousser.', 'Eat the frog first', 'Do the most important task first, especially the one you feel like putting off.', 'published'),
  ('P011', 'clarity_goals', 'Loi des 80/20', 'Une minorité d''actions produit l''essentiel des résultats : on les identifie et on les place en priorité.', 'The 80/20 rule', 'A minority of actions drives most results: identify them and put them first.', 'published'),
  ('P012', 'clarity_goals', 'L''important avant l''urgent', 'Investir du temps dans l''important non urgent évite de vivre en mode pompier.', 'Important before urgent', 'Investing time in what is important but not urgent stops you living in firefighting mode.', 'published'),
  ('P013', 'clarity_goals', 'Vider sa tête', 'Noter toutes ses tâches et idées dans un système fiable libère l''esprit pour agir.', 'Capture everything', 'Recording every task and idea in a trusted system frees the mind to act.', 'published'),
  ('P014', 'clarity_goals', 'La prochaine action concrète', 'Un projet avance quand on définit la prochaine action visible et faisable.', 'The next physical action', 'A project moves when you define the next visible, doable action.', 'published'),
  ('P015', 'clarity_goals', 'Revue hebdomadaire', 'Revoir chaque semaine objectifs, projets et engagements garde le cap.', 'Weekly review', 'Reviewing goals, projects and commitments every week keeps you on course.', 'published'),
  ('P016', 'clarity_goals', 'Décider vite, changer lentement', 'Les personnes qui réussissent tranchent rapidement et ne changent d''avis qu''avec de bonnes raisons.', 'Decide fast, change slowly', 'Successful people decide quickly and change their minds only for good reasons.', 'published'),
  ('P017', 'clarity_goals', 'L''identité avant le résultat', 'Définir qui l''on veut devenir guide mieux le comportement que viser un seul résultat.', 'Identity before outcome', 'Defining who you want to become guides behaviour better than chasing a single result.', 'published'),
  ('P018', 'clarity_goals', 'Savoir dire non', 'Refuser ce qui ne sert pas l''objectif protège son temps et son énergie.', 'Know what to say no to', 'Declining what does not serve the goal protects your time and energy.', 'published'),
  ('P019', 'discipline_habits', '1 % de mieux chaque jour', 'De petites améliorations quotidiennes se cumulent en grands résultats.', '1% better every day', 'Small daily improvements compound into large results.', 'published'),
  ('P020', 'discipline_habits', 'Les systèmes plutôt que les objectifs', 'Ce sont les routines quotidiennes, plus que l''objectif, qui déterminent le résultat.', 'Systems over goals', 'Daily routines, more than the goal itself, determine the outcome.', 'published'),
  ('P021', 'discipline_habits', 'Rendre l''habitude évidente', 'Placer des signaux visibles dans son environnement déclenche la bonne habitude.', 'Make it obvious', 'Visible cues in your environment trigger the right habit.', 'published'),
  ('P022', 'discipline_habits', 'Rendre l''habitude attrayante', 'Associer une habitude à quelque chose d''agréable augmente l''envie de la faire.', 'Make it attractive', 'Pairing a habit with something enjoyable makes you want to do it.', 'published'),
  ('P023', 'discipline_habits', 'Rendre l''habitude facile', 'Réduire la friction pour les bonnes habitudes et l''augmenter pour les mauvaises.', 'Make it easy', 'Reduce friction for good habits and add friction to bad ones.', 'published'),
  ('P024', 'discipline_habits', 'Rendre l''habitude satisfaisante', 'Une récompense immédiate, même un simple suivi visuel, ancre l''habitude.', 'Make it satisfying', 'An immediate reward, even simple visual tracking, locks the habit in.', 'published'),
  ('P025', 'discipline_habits', 'Empiler les habitudes', 'Accrocher une nouvelle habitude à une habitude existante : « après X, je fais Y ».', 'Habit stacking', 'Attach a new habit to an existing one: “after X, I do Y”.', 'published'),
  ('P026', 'discipline_habits', 'La règle des deux minutes', 'Réduire une habitude à une version de deux minutes pour commencer sans effort.', 'The two-minute rule', 'Scale a habit down to a two-minute version so starting takes no effort.', 'published'),
  ('P027', 'discipline_habits', 'Ne jamais manquer deux fois', 'Rater un jour arrive ; rater deux jours de suite installe une mauvaise habitude.', 'Never miss twice', 'Missing a day happens; missing two in a row starts a new bad habit.', 'published'),
  ('P028', 'discipline_habits', 'La boucle signal-routine-récompense', 'Pour changer une habitude, on garde le signal et la récompense et on remplace la routine.', 'The cue-routine-reward loop', 'To change a habit, keep the cue and the reward and replace the routine.', 'published'),
  ('P029', 'discipline_habits', 'Les habitudes clés', 'Certaines habitudes en entraînent d''autres par effet domino.', 'Keystone habits', 'Some habits set off others in a domino effect.', 'published'),
  ('P030', 'discipline_habits', 'La routine matinale', 'Une routine du matin structurée lance la journée avec intention plutôt qu''en réaction.', 'Morning routine', 'A structured morning routine starts the day with intention rather than in reaction.', 'published'),
  ('P031', 'discipline_habits', 'Les six pratiques du matin', 'Silence, affirmations, visualisation, exercice, lecture et écriture, même quelques minutes chacune.', 'The six morning practices', 'Silence, affirmations, visualisation, exercise, reading and writing, even a few minutes each.', 'published'),
  ('P032', 'discipline_habits', 'La persévérance', 'La plupart des échecs viennent d''un abandon trop tôt ; la persévérance se travaille.', 'Persistence', 'Most failures come from giving up too soon; persistence can be trained.', 'published'),
  ('P033', 'discipline_habits', 'L''environnement plutôt que la volonté', 'Mieux vaut organiser son environnement que compter sur sa volonté, qui fluctue.', 'Environment over willpower', 'Better to design your environment than to rely on willpower, which fluctuates.', 'published'),
  ('P034', 'discipline_habits', 'Suivre ses habitudes', 'Mesurer ce que l''on fait rend le progrès visible et motivant.', 'Track your habits', 'Measuring what you do makes progress visible and motivating.', 'published'),
  ('P035', 'discipline_habits', 'Le contrat d''engagement', 'S''engager publiquement ou auprès d''un partenaire augmente le coût de l''abandon.', 'Commitment contract', 'Committing publicly or to a partner raises the cost of quitting.', 'published'),
  ('P036', 'discipline_habits', 'La proactivité', 'Se concentrer sur ce que l''on peut influencer plutôt que subir ce que l''on ne contrôle pas.', 'Be proactive', 'Focus on what you can influence rather than what you cannot control.', 'published'),
  ('P037', 'discipline_habits', 'Le travail en profondeur', 'Des blocs de concentration sans distraction produisent un travail de grande valeur.', 'Deep work', 'Distraction-free blocks of focus produce high-value work.', 'published'),
  ('P038', 'discipline_habits', 'Les rituels de concentration', 'Un lieu, une durée et des règles fixes facilitent l''entrée en concentration.', 'Focus rituals', 'A set place, duration and rules make it easier to get into focus.', 'published'),
  ('P039', 'discipline_habits', 'Accepter l''ennui', 'Résister aux distractions permanentes entraîne la capacité d''attention.', 'Embrace boredom', 'Resisting constant distraction trains your attention span.', 'published'),
  ('P040', 'discipline_habits', 'Le rituel de fin de journée', 'Clôturer sa journée de travail par un rituel fixe libère l''esprit pour la soirée.', 'Shutdown ritual', 'Closing the workday with a fixed ritual frees the mind for the evening.', 'published'),
  ('P041', 'money_wealth', 'Actif ou passif', 'Un actif met de l''argent dans votre poche, un passif en retire.', 'Assets vs liabilities', 'An asset puts money in your pocket; a liability takes it out.', 'published'),
  ('P042', 'money_wealth', 'Se payer en premier', 'Mettre de côté une part de chaque revenu avant toute dépense.', 'Pay yourself first', 'Set aside part of every income before any spending.', 'published'),
  ('P043', 'money_wealth', 'Garder au moins un dixième', 'Épargner au moins 10 % de ce que l''on gagne, quel que soit le revenu.', 'Keep at least a tenth', 'Save at least 10% of what you earn, whatever your income.', 'published'),
  ('P044', 'money_wealth', 'Maîtriser ses dépenses', 'Distinguer besoins et envies et fixer un budget à ses dépenses.', 'Control your expenses', 'Separate needs from wants and budget your spending.', 'published'),
  ('P045', 'money_wealth', 'Faire travailler son argent', 'L''argent épargné doit être placé pour produire des revenus.', 'Make your money work', 'Saved money should be invested to generate income.', 'published'),
  ('P046', 'money_wealth', 'Protéger son capital', 'Éviter les placements que l''on ne comprend pas et les promesses de gains rapides.', 'Guard your capital', 'Avoid investments you do not understand and promises of quick gains.', 'published'),
  ('P047', 'money_wealth', 'Augmenter sa capacité à gagner', 'Investir dans ses compétences augmente ses revenus futurs.', 'Increase your earning power', 'Investing in your skills raises your future income.', 'published'),
  ('P048', 'money_wealth', 'L''intelligence financière', 'Comprendre comptabilité, investissement, marchés et fiscalité est un avantage décisif.', 'Financial literacy', 'Understanding accounting, investing, markets and tax is a decisive advantage.', 'published'),
  ('P049', 'money_wealth', 'Travailler pour apprendre', 'Choisir ses expériences pour les compétences qu''elles apportent, pas seulement pour le salaire.', 'Work to learn', 'Choose experiences for the skills they bring, not just the pay.', 'published'),
  ('P050', 'money_wealth', '« Comment puis-je me le permettre ? »', 'Remplacer « je ne peux pas me le payer » par une question qui pousse à chercher des solutions.', '“How can I afford it?”', 'Replace “I can''t afford it” with a question that makes you look for solutions.', 'published'),
  ('P051', 'money_wealth', 'La peur et l''avidité', 'Reconnaître ses émotions face à l''argent évite les mauvaises décisions.', 'Fear and greed', 'Recognising your emotions about money prevents bad decisions.', 'published'),
  ('P052', 'money_wealth', 'Les intérêts composés', 'Le temps est le premier levier d''enrichissement : commencer tôt compte plus que le montant.', 'Compounding', 'Time is the main lever of wealth: starting early matters more than the amount.', 'published'),
  ('P053', 'money_wealth', 'Savoir ce qui est « assez »', 'Définir son « assez » protège des risques inutiles et de la comparaison sans fin.', 'Knowing what is enough', 'Defining your “enough” protects you from needless risk and endless comparison.', 'published'),
  ('P054', 'money_wealth', 'L''épargne de précaution', 'Une réserve d''argent donne de la liberté et absorbe l''imprévu.', 'Margin of safety', 'A cash reserve gives freedom and absorbs the unexpected.', 'published'),
  ('P055', 'money_wealth', 'La richesse ne se voit pas', 'La vraie richesse est l''argent non dépensé, pas les signes extérieurs.', 'Wealth is what you don''t see', 'Real wealth is money not spent, not outward signs of it.', 'published'),
  ('P056', 'money_wealth', 'Le comportement avant la technique', 'Bien gérer son argent dépend davantage du comportement que des connaissances.', 'Behaviour beats knowledge', 'Managing money well depends more on behaviour than on knowledge.', 'published'),
  ('P057', 'money_wealth', 'Préparer l''avenir', 'Organiser dès maintenant ses revenus futurs et sa retraite.', 'Provide for the future', 'Start organising your future income and retirement now.', 'published'),
  ('P058', 'money_wealth', 'Prendre conseil auprès des compétents', 'Demander conseil à ceux qui ont réussi dans le domaine concerné, pas à n''importe qui.', 'Seek advice from the competent', 'Ask for advice from people who have succeeded in that specific field.', 'published'),
  ('P059', 'money_wealth', 'Le savoir spécialisé', 'Le savoir utile est celui que l''on organise et applique au service d''un objectif.', 'Specialised knowledge', 'Useful knowledge is knowledge organised and applied towards a goal.', 'published'),
  ('P060', 'money_wealth', 'S''occuper de ses propres affaires', 'Construire sa colonne d''actifs en parallèle de son travail principal.', 'Mind your own business', 'Build your asset column alongside your main job.', 'published'),
  ('P061', 'business_career', 'L''imagination créatrice', 'Les idées naissent de la combinaison de connaissances existantes ; on les cultive volontairement.', 'Creative imagination', 'Ideas come from combining existing knowledge; cultivate them deliberately.', 'published'),
  ('P062', 'business_career', 'La planification organisée', 'Un plan solide, révisé après chaque échec et porté par une équipe, transforme le désir en résultat.', 'Organised planning', 'A solid plan, revised after each setback and backed by a team, turns desire into results.', 'published'),
  ('P063', 'business_career', 'Les qualités du leader', 'Courage, maîtrise de soi, sens de la justice, décision et plans précis fondent le leadership.', 'Qualities of a leader', 'Courage, self-control, fairness, decisiveness and clear plans are the basis of leadership.', 'published'),
  ('P064', 'business_career', 'Vendre ses services', 'Chacun vend quelque chose ; la qualité et l''esprit de service font la valeur.', 'Selling your services', 'Everyone sells something; quality and a spirit of service create value.', 'published'),
  ('P065', 'business_career', 'En faire plus que ce pour quoi on est payé', 'Donner plus que prévu crée une réputation et des opportunités.', 'Go the extra mile', 'Giving more than expected builds reputation and opportunity.', 'published'),
  ('P066', 'business_career', 'Apprendre à vendre', 'Savoir vendre et communiquer est une compétence clé de la réussite.', 'Learn to sell', 'Being able to sell and communicate is a key skill for success.', 'published'),
  ('P067', 'business_career', 'Penser gagnant-gagnant', 'Chercher des accords bénéfiques pour toutes les parties.', 'Think win-win', 'Look for agreements that benefit every party.', 'published'),
  ('P068', 'business_career', 'La synergie', 'Un travail collectif bien mené produit plus que la somme des contributions individuelles.', 'Synergise', 'Well-run teamwork produces more than the sum of individual contributions.', 'published'),
  ('P069', 'business_career', 'Les compétences rares et précieuses', 'La valeur sur le marché vient de compétences difficiles à acquérir.', 'Rare and valuable skills', 'Market value comes from skills that are hard to acquire.', 'published'),
  ('P070', 'business_career', 'Apprendre vite des choses difficiles', 'La pratique délibérée et concentrée accélère l''apprentissage.', 'Learn hard things quickly', 'Deliberate, focused practice speeds up learning.', 'published'),
  ('P071', 'business_career', 'Planifier ses heures', 'Attribuer chaque heure de travail à une tâche évite de se laisser porter.', 'Time blocking', 'Assigning every working hour to a task stops you drifting.', 'published'),
  ('P072', 'business_career', 'L''échec comme information', 'Un échec temporaire est une information pour ajuster, pas un verdict.', 'Failure as feedback', 'A temporary failure is information to adjust, not a verdict.', 'published'),
  ('P073', 'business_career', 'Les domaines de résultats clés', 'Identifier les quelques domaines qui déterminent ses résultats et y exceller.', 'Key result areas', 'Identify the few areas that determine your results and excel in them.', 'published'),
  ('P074', 'business_career', 'Se préparer avant de commencer', 'Rassembler outils et informations avant de commencer accélère l''exécution.', 'Prepare before you start', 'Gathering tools and information before starting speeds up execution.', 'published'),
  ('P075', 'business_career', 'Découper les grandes tâches', 'Découper une grosse tâche en petites étapes faciles à lancer.', 'Slice big tasks', 'Break a big task into small steps that are easy to start.', 'published'),
  ('P076', 'business_career', 'Se fixer des échéances', 'Une échéance crée l''urgence qui fait passer à l''action.', 'Set deadlines', 'A deadline creates the urgency that gets you moving.', 'published'),
  ('P077', 'mindset_beliefs', 'La confiance en son objectif', 'Croire en son objectif renforce l''engagement ; cette confiance se construit par la répétition et les preuves.', 'Faith in your goal', 'Believing in your goal strengthens commitment; that belief is built through repetition and evidence.', 'published'),
  ('P078', 'mindset_beliefs', 'L''autosuggestion', 'Relire et répéter son objectif chaque jour ancre la conviction.', 'Autosuggestion', 'Rereading and repeating your goal every day anchors conviction.', 'published'),
  ('P079', 'mindset_beliefs', 'Maîtriser ses pensées', 'Ce sur quoi on se concentre influence ce que l''on remarque et ce que l''on entreprend.', 'Master your thoughts', 'What you focus on shapes what you notice and what you undertake.', 'published'),
  ('P080', 'mindset_beliefs', 'La gratitude', 'Remarquer ce qui va bien améliore l''humeur et entretient la motivation.', 'Gratitude', 'Noticing what is going well lifts mood and sustains motivation.', 'published'),
  ('P081', 'mindset_beliefs', 'Les peurs fondamentales', 'Peur de la pauvreté, de la critique, de la maladie, de perdre l''amour, de vieillir, de mourir : les nommer aide à les dépasser.', 'The basic fears', 'Fear of poverty, criticism, illness, losing love, ageing and death: naming them helps you get past them.', 'published'),
  ('P082', 'mindset_beliefs', 'Indécision et doute', 'L''indécision nourrit la peur ; décider la fait reculer.', 'Indecision and doubt', 'Indecision feeds fear; deciding pushes it back.', 'published'),
  ('P083', 'mindset_beliefs', 'La mentalité de croissance', 'Les capacités se développent par l''effort, la stratégie et l''apprentissage.', 'Growth mindset', 'Abilities develop through effort, strategy and learning.', 'published'),
  ('P084', 'mindset_beliefs', 'Le pouvoir du « pas encore »', 'Remplacer « je ne sais pas faire » par « je ne sais pas encore faire ».', 'The power of “yet”', 'Replace “I can''t do it” with “I can''t do it yet”.', 'published'),
  ('P085', 'mindset_beliefs', 'Apprendre de la critique', 'Utiliser la critique comme une information plutôt que comme une menace.', 'Learn from criticism', 'Treat criticism as information rather than a threat.', 'published'),
  ('P086', 'mindset_beliefs', 'S''inspirer de la réussite des autres', 'Le succès des autres est une source d''apprentissage, pas une menace.', 'Be inspired by others'' success', 'Other people''s success is a source of learning, not a threat.', 'published'),
  ('P087', 'mindset_beliefs', 'Des affirmations tournées vers l''action', 'Une affirmation utile dit ce que l''on s''engage à faire, pas seulement ce que l''on souhaite.', 'Action-oriented affirmations', 'A useful affirmation states what you commit to do, not just what you wish for.', 'published'),
  ('P088', 'mindset_beliefs', 'La responsabilité totale', 'Assumer la responsabilité de sa situation redonne du pouvoir d''agir.', 'Total responsibility', 'Owning your situation gives you back the power to act.', 'published'),
  ('P089', 'mindset_beliefs', 'L''optimisme réaliste', 'Croire en la réussite tout en anticipant les obstacles.', 'Realistic optimism', 'Believe you will succeed while anticipating the obstacles.', 'published'),
  ('P090', 'mindset_beliefs', 'Voir l''obstacle comme une occasion', 'Chaque difficulté porte une leçon ou une opportunité à chercher.', 'Obstacles as opportunities', 'Every difficulty carries a lesson or an opportunity worth looking for.', 'published'),
  ('P091', 'mindset_beliefs', 'Canaliser ses émotions fortes', 'Rediriger l''énergie des émotions intenses vers son objectif plutôt que la subir.', 'Channel strong emotions', 'Redirect the energy of intense emotions towards your goal instead of being carried by it.', 'published'),
  ('P092', 'mindset_beliefs', 'Écouter son intuition', 'L''intuition, nourrie par l''expérience, complète l''analyse.', 'Listen to your intuition', 'Intuition, fed by experience, complements analysis.', 'published'),
  ('P093', 'mindset_beliefs', 'Le silence', 'Quelques minutes de calme réduisent le stress et clarifient l''esprit.', 'Silence', 'A few minutes of calm reduce stress and clear the mind.', 'published'),
  ('P094', 'mindset_beliefs', 'Écrire pour y voir clair', 'Noter ses pensées aide à les organiser et à tirer les leçons de ses journées.', 'Write to think clearly', 'Writing your thoughts down helps organise them and learn from your days.', 'published'),
  ('P095', 'relationships_network', 'Le mastermind', 'S''entourer d''un groupe qui partage ses ambitions démultiplie les idées et l''énergie.', 'The mastermind', 'Surrounding yourself with a group that shares your ambitions multiplies ideas and energy.', 'published'),
  ('P096', 'relationships_network', 'Ne pas critiquer', 'La critique braque ; chercher à comprendre ouvre la discussion.', 'Don''t criticise', 'Criticism puts people on the defensive; seeking to understand opens the conversation.', 'published'),
  ('P097', 'relationships_network', 'Exprimer une reconnaissance sincère', 'Dire précisément et sincèrement ce que l''on apprécie chez l''autre.', 'Give sincere appreciation', 'Say precisely and sincerely what you value in someone.', 'published'),
  ('P098', 'relationships_network', 'Partir de ce que veut l''autre', 'Parler de ce que l''autre veut plutôt que de ce que l''on veut soi-même.', 'Start from what the other wants', 'Talk about what the other person wants rather than what you want.', 'published'),
  ('P099', 'relationships_network', 'S''intéresser sincèrement aux autres', 'On crée plus de liens en s''intéressant aux autres qu''en cherchant à les intéresser.', 'Be genuinely interested', 'You build more connections by being interested in others than by trying to interest them.', 'published'),
  ('P100', 'relationships_network', 'Retenir les prénoms', 'Utiliser le prénom de quelqu''un montre qu''on lui accorde de l''importance.', 'Remember names', 'Using someone''s name shows that they matter to you.', 'published'),
  ('P101', 'relationships_network', 'Savoir écouter', 'Encourager l''autre à parler de lui et écouter vraiment.', 'Be a good listener', 'Encourage others to talk about themselves and really listen.', 'published'),
  ('P102', 'relationships_network', 'Éviter les disputes', 'On ne gagne pas une dispute ; on cherche un terrain d''entente.', 'Avoid arguments', 'Nobody wins an argument; look for common ground instead.', 'published'),
  ('P103', 'relationships_network', 'Reconnaître vite ses torts', 'Admettre rapidement ses erreurs désamorce les conflits.', 'Admit mistakes quickly', 'Owning up to mistakes quickly defuses conflict.', 'published'),
  ('P104', 'relationships_network', 'Chercher d''abord à comprendre', 'Écouter avec empathie avant de chercher à être compris.', 'Seek first to understand', 'Listen with empathy before trying to be understood.', 'published'),
  ('P105', 'relationships_network', 'Le compte en banque émotionnel', 'La confiance se construit par de petits gestes réguliers, et se perd vite.', 'The emotional bank account', 'Trust is built through small, regular gestures, and lost quickly.', 'published'),
  ('P106', 'relationships_network', 'L''entourage nous façonne', 'On adopte les habitudes du groupe auquel on appartient ou veut appartenir.', 'Your circle shapes you', 'You adopt the habits of the group you belong to or want to join.', 'published'),
  ('P107', 'relationships_network', 'Le sourire', 'Une attitude chaleureuse facilite le premier contact.', 'Smile', 'A warm attitude makes first contact easier.', 'published'),
  ('P108', 'relationships_network', 'Valoriser l''autre', 'Faire sentir sincèrement à l''autre qu''il compte renforce la relation.', 'Make others feel important', 'Sincerely making others feel they matter strengthens the relationship.', 'published'),
  ('P109', 'energy_health', 'Aiguiser la scie', 'Entretenir régulièrement son corps, son esprit, ses relations et son sens.', 'Sharpen the saw', 'Regularly renew your body, mind, relationships and sense of purpose.', 'published'),
  ('P110', 'energy_health', 'Bouger chaque jour', 'Quelques minutes d''activité physique augmentent l''énergie et la clarté d''esprit.', 'Move every day', 'A few minutes of physical activity boost energy and mental clarity.', 'published'),
  ('P111', 'energy_health', 'Protéger son sommeil', 'Un sommeil suffisant conditionne la concentration et la qualité des décisions.', 'Protect your sleep', 'Enough sleep underpins focus and the quality of decisions.', 'published'),
  ('P112', 'energy_health', 'Gérer son énergie, pas seulement son temps', 'Placer les tâches exigeantes aux heures où l''on est le plus en forme.', 'Manage energy, not just time', 'Schedule demanding tasks for the hours when you are at your best.', 'published'),
  ('P113', 'energy_health', 'Les pauses régulières', 'Alterner concentration et récupération maintient la performance sur la durée.', 'Regular breaks', 'Alternating focus and recovery sustains performance over time.', 'published'),
  ('P114', 'energy_health', 'La lecture quotidienne', 'Lire quelques pages chaque jour nourrit l''apprentissage et l''inspiration.', 'Daily reading', 'Reading a few pages every day feeds learning and inspiration.', 'published'),
  ('P115', 'energy_health', 'L''hygiène numérique', 'Limiter notifications et réseaux sociaux préserve l''attention et l''énergie.', 'Digital hygiene', 'Limiting notifications and social media preserves attention and energy.', 'published');
