insert into public.exercises (id, title_fr, instructions_fr, title_en, instructions_en, domain, duration_min, difficulty, energy, time_of_day, type, personas, blockers, repeat_after_days, proof_type, status) values
  ('E001', 'Écrire son objectif principal', 'Écris ton objectif principal en une phrase : ce que tu veux, le chiffre qui prouvera qu''il est atteint et la date.', 'Write your main goal', 'Write your main goal in one sentence: what you want, the number that will prove it is achieved and the date.', 'clarity_goals', 10, 1, 'medium', 'morning', 'writing', '{}'::public.persona[], array['motivation', 'organisation']::public.blocker[], null, 'free_text', 'published'),
  ('E002', 'Ce que je donne en échange', 'Note ce que tu es prêt à donner pour atteindre ton objectif : heures par semaine, efforts, renoncements.', 'What I give in return', 'List what you are willing to give to reach your goal: hours per week, effort, sacrifices.', 'clarity_goals', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['motivation']::public.blocker[], 90, 'free_text', 'published'),
  ('E003', 'Lire son objectif matin et soir', 'Relis ton objectif à voix haute au réveil et au coucher, puis note une action prévue pour le faire avancer.', 'Read your goal morning and night', 'Read your goal aloud when you wake up and before bed, then note one planned action that moves it forward.', 'clarity_goals', 2, 1, 'low', 'morning', 'reflection', '{}'::public.persona[], array['motivation', 'confidence']::public.blocker[], 1, 'checkbox', 'published'),
  ('E004', 'Trouver son pourquoi', 'Réponds à « pourquoi est-ce important pour moi ? », puis repose la même question quatre fois sur ta réponse précédente.', 'Find your why', 'Answer “why does this matter to me?”, then ask the same question four more times about your previous answer.', 'clarity_goals', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 60, 'free_text', 'published'),
  ('E005', 'Les trois premières actions', 'Liste les trois premières actions concrètes vers ton objectif et fais la première aujourd''hui.', 'The first three actions', 'List the first three concrete actions towards your goal and do the first one today.', 'clarity_goals', 15, 2, 'medium', 'daytime', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'free_text', 'published'),
  ('E006', 'Démarrer imparfaitement', 'Choisis une tâche que tu repousses parce qu''elle n''est pas parfaite et produis-en un brouillon en 15 minutes.', 'Start imperfectly', 'Pick a task you keep postponing because it isn''t perfect and produce a rough draft in 15 minutes.', 'clarity_goals', 15, 2, 'medium', 'daytime', 'action', '{}'::public.persona[], array['procrastination', 'fear']::public.blocker[], 7, 'checkbox', 'published'),
  ('E007', 'Le discours de mes 80 ans', 'Écris ce que tu aimerais que tes proches disent de toi le jour de tes 80 ans.', 'My 80th birthday speech', 'Write what you would like your loved ones to say about you on your 80th birthday.', 'clarity_goals', 15, 3, 'medium', 'evening', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 180, 'free_text', 'published'),
  ('E008', 'Ma vie dans 10 ans', 'Décris une journée type de ta vie dans 10 ans : où, avec qui, à faire quoi.', 'My life in 10 years', 'Describe a typical day in your life ten years from now: where, with whom, doing what.', 'clarity_goals', 15, 2, 'medium', 'evening', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 180, 'free_text', 'published'),
  ('E009', 'Mes cinq valeurs', 'Choisis tes cinq valeurs principales et donne pour chacune un exemple récent où tu l''as respectée.', 'My five values', 'Choose your five core values and give a recent example of living each one.', 'clarity_goals', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['confidence']::public.blocker[], 180, 'free_text', 'published'),
  ('E010', 'Rédiger sa mission personnelle', 'Rédige ta mission personnelle en trois phrases maximum, à partir de tes valeurs.', 'Write your personal mission', 'Write your personal mission in three sentences at most, based on your values.', 'clarity_goals', 15, 3, 'high', 'any', 'writing', '{}'::public.persona[], '{}'::public.blocker[], 180, 'free_text', 'published'),
  ('E011', 'Une décision alignée', 'Avant une décision importante aujourd''hui, vérifie si elle respecte ta mission et note ta conclusion.', 'An aligned decision', 'Before an important decision today, check whether it fits your mission and note your conclusion.', 'clarity_goals', 5, 2, 'medium', 'daytime', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E012', 'Mon WOOP du jour', 'Note ton souhait du jour, le meilleur résultat possible, ton obstacle intérieur principal et ton plan « si… alors… ».', 'Today''s WOOP', 'Write today''s wish, the best possible outcome, your main inner obstacle and your “if… then…” plan.', 'clarity_goals', 5, 1, 'low', 'morning', 'reflection', '{}'::public.persona[], array['procrastination', 'motivation']::public.blocker[], 1, 'free_text', 'published'),
  ('E013', 'WOOP sur l''objectif principal', 'Applique WOOP à ton objectif principal et garde ton plan « si… alors… » sous les yeux toute la semaine.', 'WOOP on your main goal', 'Apply WOOP to your main goal and keep your “if… then…” plan in sight all week.', 'clarity_goals', 10, 2, 'medium', 'morning', 'reflection', '{}'::public.persona[], array['fear', 'procrastination']::public.blocker[], 14, 'free_text', 'published'),
  ('E014', 'Trois plans si-alors', 'Écris trois plans « si [situation], alors je [action] » pour les moments où tu décroches habituellement.', 'Three if-then plans', 'Write three “if [situation], then I [action]” plans for the moments when you usually drift.', 'clarity_goals', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['procrastination']::public.blocker[], 14, 'free_text', 'published'),
  ('E015', 'Visualiser puis planifier', 'Visualise deux minutes ton objectif atteint, puis deux minutes l''obstacle le plus probable, et note comment tu le franchiras.', 'Visualise, then plan', 'Picture your goal achieved for two minutes, then the most likely obstacle for two minutes, and note how you will get past it.', 'clarity_goals', 5, 1, 'low', 'morning', 'visualisation', '{}'::public.persona[], array['fear', 'motivation']::public.blocker[], 3, 'free_text', 'published'),
  ('E016', 'Un tableau de vision actionnable', 'Crée un tableau de vision de cinq images et associe à chacune une action à faire cette semaine.', 'An actionable vision board', 'Build a vision board with five images and attach one action to do this week to each.', 'clarity_goals', 30, 2, 'medium', 'any', 'visualisation', '{}'::public.persona[], array['motivation']::public.blocker[], 90, 'checkbox', 'published'),
  ('E017', 'Choisir sa grenouille', 'Le soir, choisis la tâche la plus importante de demain et note l''heure à laquelle tu la commenceras.', 'Pick your frog', 'In the evening, choose tomorrow''s most important task and note the time you will start it.', 'clarity_goals', 2, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'free_text', 'published'),
  ('E018', 'Manger la grenouille', 'Fais ta tâche la plus importante en premier, avant de lire tes e-mails et messages.', 'Eat the frog', 'Do your most important task first, before reading email and messages.', 'clarity_goals', 30, 3, 'high', 'morning', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E019', 'Le 80/20 de ma semaine', 'Liste tes activités de la semaine et repère les 20 % qui ont produit le plus de résultats.', 'The 80/20 of my week', 'List this week''s activities and spot the 20% that produced the most results.', 'clarity_goals', 15, 2, 'medium', 'evening', 'reflection', array['entrepreneur', 'employee']::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E020', 'Le 80/20 de mes revenus', 'Identifie les 20 % de clients, produits ou sources qui génèrent 80 % de tes revenus et note une action pour les développer.', 'The 80/20 of my income', 'Identify the 20% of clients, products or sources that bring in 80% of your income and note one action to grow them.', 'clarity_goals', 30, 3, 'high', 'daytime', 'reflection', array['entrepreneur']::public.persona[], array['finances', 'organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E021', 'La matrice des priorités', 'Classe les tâches de ta semaine dans les quatre cases urgent/important et planifie une tâche « importante non urgente ».', 'The priority matrix', 'Sort this week''s tasks into the four urgent/important boxes and schedule one “important, not urgent” task.', 'clarity_goals', 15, 2, 'medium', 'morning', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E022', 'Un bloc pour l''important', 'Réserve 30 minutes aujourd''hui à une tâche importante mais non urgente et protège ce créneau.', 'A block for what matters', 'Block 30 minutes today for an important but non-urgent task and protect that slot.', 'clarity_goals', 30, 3, 'high', 'daytime', 'action', '{}'::public.persona[], array['organisation', 'procrastination']::public.blocker[], 3, 'checkbox', 'published'),
  ('E023', 'Vider sa tête', 'Note sur une seule liste tout ce qui t''occupe l''esprit : tâches, idées, soucis, sans trier.', 'Brain dump', 'Write everything on your mind on one list: tasks, ideas, worries, without sorting.', 'clarity_goals', 15, 1, 'low', 'any', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 14, 'numeric', 'published'),
  ('E024', 'Trier sa liste', 'Pour chaque élément de ta liste : le faire tout de suite s''il prend moins de deux minutes, le planifier, le déléguer ou l''abandonner.', 'Sort your list', 'For each item: do it now if it takes under two minutes, schedule it, delegate it or drop it.', 'clarity_goals', 15, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 14, 'checkbox', 'published'),
  ('E025', 'La prochaine action de chaque projet', 'Pour chacun de tes projets en cours, écris la prochaine action physique et visible.', 'Each project''s next action', 'For each ongoing project, write the next physical, visible action.', 'clarity_goals', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['procrastination', 'organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E026', 'Revue hebdomadaire guidée', 'Fais le bilan de ta semaine : réussites, objectifs en retard, engagements à venir et trois priorités pour la semaine prochaine.', 'Guided weekly review', 'Review your week: wins, lagging goals, upcoming commitments and three priorities for next week.', 'clarity_goals', 30, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E027', 'Décider en cinq minutes', 'Prends en cinq minutes chrono une décision que tu repousses depuis plus d''une semaine, et note-la.', 'Decide in five minutes', 'Make a decision you have been postponing for over a week, in five minutes flat, and write it down.', 'clarity_goals', 5, 3, 'medium', 'daytime', 'action', '{}'::public.persona[], array['fear', 'procrastination']::public.blocker[], 7, 'free_text', 'published'),
  ('E028', 'Les décisions en attente', 'Liste tes décisions en suspens et fixe une date limite pour chacune.', 'Pending decisions', 'List your pending decisions and set a deadline for each.', 'clarity_goals', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['fear', 'organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E029', 'Je suis le genre de personne qui…', 'Complète « je suis le genre de personne qui… » avec trois phrases liées à ton objectif.', 'I am the kind of person who…', 'Complete “I am the kind of person who…” with three sentences linked to your goal.', 'clarity_goals', 5, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 30, 'free_text', 'published'),
  ('E030', 'Un vote pour son identité', 'Fais une petite action qui prouve la personne que tu veux devenir et note-la comme un « vote ».', 'A vote for your identity', 'Do one small action that proves who you want to become and record it as a “vote”.', 'clarity_goals', 5, 1, 'low', 'daytime', 'action', '{}'::public.persona[], array['confidence']::public.blocker[], 1, 'free_text', 'published'),
  ('E031', 'Ma liste « pas maintenant »', 'Écris cinq choses auxquelles tu dis non, ou pas maintenant, pour protéger ton objectif.', 'My “not now” list', 'Write five things you are saying no, or not now, to in order to protect your goal.', 'clarity_goals', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E032', 'Dire non une fois', 'Refuse aujourd''hui une demande qui ne sert pas tes priorités, poliment et sans longue justification.', 'Say no once', 'Decline one request today that doesn''t serve your priorities, politely and without a long justification.', 'clarity_goals', 5, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['confidence', 'fear']::public.blocker[], 7, 'checkbox', 'published'),
  ('E033', 'Découper l''objectif en jalons', 'Découpe ton objectif en trois à cinq jalons datés.', 'Break the goal into milestones', 'Split your goal into three to five dated milestones.', 'clarity_goals', 15, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E034', 'L''objectif de la semaine', 'Fixe un objectif mesurable pour la semaine, relié au prochain jalon.', 'Goal of the week', 'Set one measurable goal for the week, tied to the next milestone.', 'clarity_goals', 5, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E035', 'Mesurer l''avancement', 'Mets à jour la valeur actuelle de ton objectif et note l''écart avec la trajectoire prévue.', 'Measure progress', 'Update your goal''s current value and note the gap with the planned trajectory.', 'clarity_goals', 2, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 7, 'numeric', 'published'),
  ('E036', 'Les trois priorités du jour', 'Le matin, choisis trois priorités au maximum pour la journée.', 'Today''s three priorities', 'In the morning, choose no more than three priorities for the day.', 'clarity_goals', 2, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 1, 'free_text', 'published'),
  ('E037', 'Le pré-mortem', 'Imagine que ton projet a échoué dans un an : liste les cinq causes les plus probables et une parade pour chacune.', 'Pre-mortem', 'Imagine your project failed a year from now: list the five most likely causes and a countermeasure for each.', 'clarity_goals', 15, 3, 'medium', 'any', 'reflection', array['entrepreneur', 'career_changer']::public.persona[], array['fear']::public.blocker[], 90, 'free_text', 'published'),
  ('E038', 'Lettre de mon futur moi', 'Écris une lettre de toi dans trois ans qui raconte comment tu as atteint ton objectif.', 'Letter from my future self', 'Write a letter from yourself three years from now describing how you reached your goal.', 'clarity_goals', 15, 2, 'medium', 'evening', 'writing', '{}'::public.persona[], array['motivation', 'confidence']::public.blocker[], 180, 'free_text', 'published'),
  ('E039', 'La roue de la vie', 'Note de 1 à 10 ta satisfaction dans huit domaines de vie et choisis celui à améliorer en premier.', 'The wheel of life', 'Rate your satisfaction from 1 to 10 in eight areas of life and choose the one to improve first.', 'clarity_goals', 10, 1, 'low', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 90, 'numeric', 'published'),
  ('E040', 'Un objectif SMART', 'Reformule ton objectif pour qu''il soit spécifique, mesurable, atteignable, réaliste et daté.', 'A SMART goal', 'Rewrite your goal so it is specific, measurable, achievable, realistic and time-bound.', 'clarity_goals', 10, 1, 'low', 'any', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E041', 'Le plus petit pas', 'Trouve l''action la plus petite possible vers ton objectif, moins de deux minutes, et fais-la maintenant.', 'The smallest step', 'Find the smallest possible action towards your goal, under two minutes, and do it now.', 'clarity_goals', 2, 1, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E042', 'L''audit de l''agenda', 'Regarde ton agenda des sept derniers jours : quelle part de ton temps a servi ton objectif ? Note un pourcentage.', 'Calendar audit', 'Look at the last seven days of your calendar: what share of your time served your goal? Note a percentage.', 'clarity_goals', 10, 2, 'medium', 'evening', 'reflection', array['entrepreneur', 'employee']::public.persona[], array['organisation']::public.blocker[], 14, 'numeric', 'published'),
  ('E043', 'Planifier demain dès ce soir', 'Avant de te coucher, place dans ton agenda les créneaux de demain pour tes priorités.', 'Plan tomorrow tonight', 'Before bed, put tomorrow''s slots for your priorities in your calendar.', 'clarity_goals', 5, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E044', 'Un projet à abandonner', 'Identifie un projet ou un engagement qui te disperse et décide de l''arrêter ou de le mettre en pause.', 'A project to drop', 'Identify one project or commitment that scatters your energy and decide to stop or pause it.', 'clarity_goals', 10, 3, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation', 'fear']::public.blocker[], 60, 'free_text', 'published'),
  ('E045', 'Mes rôles et leurs objectifs', 'Liste tes rôles principaux (professionnel, familial, personnel) et fixe un objectif de la semaine pour chacun.', 'My roles and their goals', 'List your main roles (work, family, personal) and set one goal for the week in each.', 'clarity_goals', 10, 2, 'medium', 'morning', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'free_text', 'published'),
  ('E046', 'Ma définition de la réussite', 'Écris ce que « réussir » veut dire pour toi, au-delà de l''argent.', 'My definition of success', 'Write what “success” means to you, beyond money.', 'clarity_goals', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 180, 'free_text', 'published'),
  ('E047', 'L''obstacle intérieur récurrent', 'Identifie l''habitude ou la pensée qui t''a le plus freiné ce mois-ci et écris un plan si-alors pour la contrer.', 'Your recurring inner obstacle', 'Identify the habit or thought that held you back most this month and write an if-then plan to counter it.', 'clarity_goals', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['procrastination', 'fear', 'confidence']::public.blocker[], 30, 'free_text', 'published'),
  ('E048', 'Annoncer son objectif', 'Partage ton objectif et ton échéance avec une personne de confiance qui te demandera régulièrement où tu en es.', 'Announce your goal', 'Share your goal and deadline with a trusted person who will regularly ask how it is going.', 'clarity_goals', 5, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['fear', 'motivation']::public.blocker[], 90, 'checkbox', 'published'),
  ('E049', 'Bilan mensuel de l''objectif', 'Compare ton avancement à ton plan et décide : garder le cap, accélérer ou ajuster l''échéance.', 'Monthly goal review', 'Compare your progress with your plan and decide: stay the course, speed up or adjust the deadline.', 'clarity_goals', 15, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E050', 'Les questions du soir', 'Réponds : qu''est-ce qui m''a rapproché de mon objectif aujourd''hui ? Qu''est-ce qui m''en a éloigné ?', 'Evening questions', 'Answer: what moved me closer to my goal today? What pulled me away from it?', 'clarity_goals', 2, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 1, 'free_text', 'published'),
  ('E051', 'Mon 1 % du jour', 'Choisis un domaine et améliore-le d''un tout petit cran aujourd''hui (une page de plus, cinq minutes de plus…), puis note-le.', 'My 1% today', 'Pick one area and improve it by a tiny notch today (one more page, five more minutes…), then note it.', 'discipline_habits', 5, 1, 'low', 'daytime', 'action', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'free_text', 'published'),
  ('E052', 'Le journal des petits progrès', 'Note chaque soir une petite amélioration de ta journée, même minime.', 'Small wins log', 'Each evening, note one small improvement from your day, however minor.', 'discipline_habits', 2, 1, 'low', 'evening', 'writing', '{}'::public.persona[], array['confidence', 'motivation']::public.blocker[], 1, 'free_text', 'published'),
  ('E053', 'Du but au système', 'Pour ton objectif principal, écris le système quotidien qui y mène : quoi, quand, où, combien de temps.', 'From goal to system', 'For your main goal, write the daily system that leads to it: what, when, where, for how long.', 'discipline_habits', 15, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E054', 'L''audit de ma routine', 'Liste ce que tu fais un jour normal, du réveil au coucher, et marque chaque habitude en +, − ou =.', 'Audit my routine', 'List what you do on a normal day, from waking to bed, and mark each habit +, − or =.', 'discipline_habits', 15, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 60, 'free_text', 'published'),
  ('E055', 'Placer un signal visible', 'Pose dans ton environnement un objet qui déclenche ta nouvelle habitude (livre sur l''oreiller, gourde sur le bureau…).', 'Place a visible cue', 'Put an object in your environment that triggers your new habit (book on the pillow, water bottle on the desk…).', 'discipline_habits', 5, 1, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'checkbox', 'published'),
  ('E056', 'Une heure et un lieu précis', 'Pour une habitude, écris « je ferai [habitude] à [heure] à [lieu] ».', 'An exact time and place', 'For one habit, write “I will [habit] at [time] in [place]”.', 'discipline_habits', 2, 1, 'low', 'any', 'writing', '{}'::public.persona[], array['procrastination', 'organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E057', 'Cacher les signaux des mauvaises habitudes', 'Retire de ta vue un objet qui déclenche une mauvaise habitude (téléphone, sucreries, télécommande).', 'Hide bad-habit cues', 'Remove from sight one object that triggers a bad habit (phone, sweets, remote).', 'discipline_habits', 5, 1, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'checkbox', 'published'),
  ('E058', 'Le couplage plaisir', 'Associe une habitude que tu repousses à une chose que tu aimes : « je n''écoute mon podcast préféré que pendant [habitude] ».', 'Temptation bundling', 'Pair a habit you postpone with something you love: “I only listen to my favourite podcast while [habit]”.', 'discipline_habits', 5, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['motivation', 'procrastination']::public.blocker[], 30, 'free_text', 'published'),
  ('E059', 'De « je dois » à « j''ai la chance de »', 'Réécris trois obligations du jour en commençant par « j''ai la chance de… ».', 'From “I have to” to “I get to”', 'Rewrite three of today''s obligations starting with “I get to…”.', 'discipline_habits', 2, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 7, 'free_text', 'published'),
  ('E060', 'Préparer la veille', 'Prépare ce soir tout ce qu''il faut pour ton habitude de demain (tenue, matériel, document ouvert).', 'Prepare the night before', 'Tonight, set out everything needed for tomorrow''s habit (clothes, gear, document open).', 'discipline_habits', 5, 1, 'low', 'evening', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E061', 'Ajouter de la friction', 'Ajoute une étape qui rend une mauvaise habitude plus difficile (déconnexion d''une appli, téléphone dans une autre pièce).', 'Add friction', 'Add one step that makes a bad habit harder (log out of an app, phone in another room).', 'discipline_habits', 5, 2, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'checkbox', 'published'),
  ('E062', 'Réduire les étapes', 'Liste les étapes qui précèdent une bonne habitude et supprimes-en au moins une.', 'Cut the steps', 'List the steps that come before a good habit and remove at least one.', 'discipline_habits', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'free_text', 'published'),
  ('E063', 'La récompense immédiate', 'Choisis une petite récompense saine à t''accorder juste après ton habitude du jour.', 'Immediate reward', 'Choose a small, healthy reward to give yourself right after today''s habit.', 'discipline_habits', 2, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['motivation']::public.blocker[], 14, 'free_text', 'published'),
  ('E064', 'La tirelire des habitudes', 'Chaque fois que tu fais ton habitude ou évites un achat impulsif, mets 1 € de côté pour un plaisir choisi à l''avance.', 'The habit jar', 'Each time you do your habit or skip an impulse purchase, set aside €1 for a treat chosen in advance.', 'discipline_habits', 2, 1, 'low', 'any', 'action', '{}'::public.persona[], array['motivation', 'finances']::public.blocker[], 1, 'numeric', 'published'),
  ('E065', 'Ma pile d''habitudes', 'Écris trois habitudes accrochées à des habitudes existantes : « après mon café, je… ».', 'My habit stack', 'Write three habits attached to existing ones: “after my coffee, I…”.', 'discipline_habits', 5, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E066', 'Tester une pile', 'Applique aujourd''hui une de tes piles d''habitudes et note si l''enchaînement a fonctionné.', 'Test a stack', 'Use one of your habit stacks today and note whether the chain worked.', 'discipline_habits', 5, 1, 'low', 'daytime', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E067', 'La version deux minutes', 'Réduis une habitude que tu peines à tenir à une version de deux minutes et fais-la aujourd''hui.', 'The two-minute version', 'Shrink a habit you struggle with to a two-minute version and do it today.', 'discipline_habits', 2, 1, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination', 'motivation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E068', 'Juste commencer', 'Lance la tâche que tu repousses en te promettant de pouvoir t''arrêter au bout de deux minutes.', 'Just start', 'Start the task you are avoiding, promising yourself you may stop after two minutes.', 'discipline_habits', 2, 1, 'low', 'daytime', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E069', 'Le plan de rattrapage', 'Écris la version minimale que tu feras le lendemain d''un raté, pour ne jamais manquer deux fois.', 'Recovery plan', 'Write the minimal version you will do the day after a miss, so you never miss twice.', 'discipline_habits', 5, 1, 'low', 'evening', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 30, 'free_text', 'published'),
  ('E070', 'Reprendre après un raté', 'Tu as manqué une habitude hier : fais-en aujourd''hui au moins la version deux minutes.', 'Bounce back', 'You missed a habit yesterday: do at least its two-minute version today.', 'discipline_habits', 2, 1, 'low', 'any', 'action', '{}'::public.persona[], array['motivation', 'confidence']::public.blocker[], 1, 'checkbox', 'published'),
  ('E071', 'Décortiquer une mauvaise habitude', 'Pour une habitude à changer, note le signal qui la déclenche, la routine et la récompense que tu en tires vraiment.', 'Dissect a bad habit', 'For a habit you want to change, note the cue that triggers it, the routine and the reward you really get from it.', 'discipline_habits', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'free_text', 'published'),
  ('E072', 'Remplacer la routine', 'Garde le même signal et la même récompense, et choisis une nouvelle routine à tester cette semaine.', 'Replace the routine', 'Keep the same cue and reward, and choose a new routine to test this week.', 'discipline_habits', 5, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 30, 'free_text', 'published'),
  ('E073', 'Noter ses envies', 'Chaque fois que l''envie de ta mauvaise habitude arrive aujourd''hui, note l''heure, le lieu et ce que tu ressentais.', 'Log your cravings', 'Each time the urge for your bad habit comes up today, note the time, the place and what you were feeling.', 'discipline_habits', 5, 2, 'low', 'daytime', 'writing', '{}'::public.persona[], array['procrastination']::public.blocker[], 14, 'numeric', 'published'),
  ('E074', 'Trouver son habitude clé', 'Parmi tes habitudes, laquelle entraîne les autres quand tu la tiens ? Fais-en la priorité du mois.', 'Find your keystone habit', 'Which of your habits pulls the others along when you keep it? Make it this month''s priority.', 'discipline_habits', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E075', 'Faire son lit', 'Commence la journée par une petite victoire : fais ton lit et range ton espace en deux minutes.', 'Make your bed', 'Start the day with a small win: make your bed and tidy your space in two minutes.', 'discipline_habits', 2, 1, 'low', 'morning', 'action', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E076', 'Concevoir sa routine matinale', 'Écris une routine du matin de 15 à 30 minutes, avec l''ordre et la durée de chaque étape.', 'Design your morning routine', 'Write a 15–30 minute morning routine with the order and length of each step.', 'discipline_habits', 15, 2, 'medium', 'evening', 'writing', '{}'::public.persona[], array['organisation']::public.blocker[], 60, 'free_text', 'published'),
  ('E077', 'Le matin miracle express', 'Fais les six pratiques du matin pendant une minute chacune : silence, affirmation, visualisation, exercice, lecture, écriture.', 'Express miracle morning', 'Do the six morning practices for one minute each: silence, affirmation, visualisation, exercise, reading, writing.', 'discipline_habits', 10, 2, 'medium', 'morning', 'action', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E078', 'Se lever 15 minutes plus tôt', 'Avance ton réveil de 15 minutes et consacre ce temps à ta priorité.', 'Get up 15 minutes earlier', 'Set your alarm 15 minutes earlier and spend that time on your priority.', 'discipline_habits', 15, 3, 'medium', 'morning', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 7, 'checkbox', 'published'),
  ('E079', 'Pas d''écran la première heure', 'Ne consulte ni e-mails ni réseaux sociaux pendant la première heure après ton réveil.', 'No screens in the first hour', 'Don''t check email or social media during the first hour after waking.', 'discipline_habits', 2, 2, 'low', 'morning', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E080', 'Le contrat de persévérance', 'Écris ce que tu feras le jour où tu auras envie d''abandonner ton objectif.', 'Persistence contract', 'Write what you will do on the day you feel like giving up on your goal.', 'discipline_habits', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['motivation', 'fear']::public.blocker[], 90, 'free_text', 'published'),
  ('E081', 'Encore une tentative', 'Reprends une chose que tu as abandonnée récemment et fais une nouvelle tentative, même courte.', 'One more attempt', 'Pick up something you recently gave up on and make one more attempt, however short.', 'discipline_habits', 15, 3, 'medium', 'daytime', 'action', '{}'::public.persona[], array['motivation', 'confidence']::public.blocker[], 30, 'checkbox', 'published'),
  ('E082', 'Mes preuves de ténacité', 'Liste trois situations où tu as tenu bon et ce que cela t''a apporté.', 'My proof of grit', 'List three times you held on and what it brought you.', 'discipline_habits', 10, 1, 'low', 'evening', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 90, 'free_text', 'published'),
  ('E083', 'Réaménager un espace', 'Réorganise un espace (bureau, cuisine, chambre) pour que la bonne habitude y soit l''option la plus simple.', 'Redesign a space', 'Rearrange a space (desk, kitchen, bedroom) so the good habit is the easiest option there.', 'discipline_habits', 30, 2, 'medium', 'any', 'action', '{}'::public.persona[], array['procrastination', 'organisation']::public.blocker[], 60, 'checkbox', 'published'),
  ('E084', 'Un lieu, un usage', 'Attribue un usage unique à un lieu (ce fauteuil pour lire, ce bureau pour travailler) et respecte-le aujourd''hui.', 'One place, one use', 'Give a place a single use (this chair for reading, this desk for work) and stick to it today.', 'discipline_habits', 5, 1, 'low', 'any', 'action', '{}'::public.persona[], array['organisation']::public.blocker[], 14, 'checkbox', 'published'),
  ('E085', 'Choisir ses habitudes à suivre', 'Choisis trois habitudes au maximum à suivre dans l''application ce mois-ci.', 'Choose habits to track', 'Choose no more than three habits to track in the app this month.', 'discipline_habits', 5, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E086', 'Le bilan des habitudes du mois', 'Regarde tes taux de réussite du mois : garde, simplifie ou remplace chaque habitude.', 'Monthly habit review', 'Look at this month''s success rates: keep, simplify or replace each habit.', 'discipline_habits', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 30, 'free_text', 'published'),
  ('E087', 'Trouver un partenaire de responsabilité', 'Demande à une personne de suivre une de tes habitudes avec toi pendant 30 jours.', 'Find an accountability partner', 'Ask someone to track one of your habits with you for 30 days.', 'discipline_habits', 10, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['motivation']::public.blocker[], 90, 'checkbox', 'published'),
  ('E088', 'Mon contrat d''habitude', 'Rédige un court contrat : l''habitude, la durée, un témoin et la conséquence en cas d''abandon.', 'My habit contract', 'Write a short contract: the habit, the duration, a witness and the consequence if you quit.', 'discipline_habits', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 90, 'free_text', 'published'),
  ('E089', 'Mon cercle d''influence', 'Liste tes préoccupations du moment, sépare ce que tu peux influencer du reste, et agis sur un élément du premier groupe.', 'My circle of influence', 'List your current concerns, separate what you can influence from the rest, and act on one item in the first group.', 'discipline_habits', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['fear']::public.blocker[], 30, 'free_text', 'published'),
  ('E090', 'Le langage proactif', 'Repère aujourd''hui une phrase réactive (« je n''ai pas le choix ») et reformule-la de façon proactive (« je choisis de… »).', 'Proactive language', 'Spot one reactive phrase today (“I have no choice”) and rephrase it proactively (“I choose to…”).', 'discipline_habits', 2, 1, 'low', 'daytime', 'reflection', '{}'::public.persona[], array['confidence']::public.blocker[], 7, 'free_text', 'published'),
  ('E091', 'Une session de travail profond', 'Travaille 30 minutes sur une tâche exigeante, notifications coupées et téléphone hors de vue.', 'A deep work session', 'Work for 30 minutes on a demanding task, notifications off and phone out of sight.', 'discipline_habits', 30, 3, 'high', 'morning', 'action', array['entrepreneur', 'employee', 'career_changer']::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E092', 'Planifier ses blocs profonds', 'Place dans ton agenda trois blocs de travail profond pour la semaine.', 'Schedule deep work blocks', 'Put three deep work blocks in your calendar for the week.', 'discipline_habits', 5, 1, 'low', 'morning', 'reflection', array['entrepreneur', 'employee', 'career_changer']::public.persona[], array['organisation']::public.blocker[], 7, 'checkbox', 'published'),
  ('E093', 'Compter ses minutes profondes', 'Note combien de minutes de travail vraiment concentré tu as faites aujourd''hui.', 'Count your deep minutes', 'Note how many minutes of truly focused work you did today.', 'discipline_habits', 2, 1, 'low', 'evening', 'reflection', array['entrepreneur', 'employee', 'career_changer']::public.persona[], '{}'::public.blocker[], 1, 'numeric', 'published'),
  ('E094', 'Mon rituel de concentration', 'Définis ton rituel : le lieu, la durée, ce qui est interdit et ce qui t''aide (musique, boisson).', 'My focus ritual', 'Define your ritual: the place, the duration, what is off-limits and what helps (music, a drink).', 'discipline_habits', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['procrastination']::public.blocker[], 60, 'free_text', 'published'),
  ('E095', 'Attendre sans téléphone', 'Dans une file ou une salle d''attente aujourd''hui, reste sans téléphone et observe.', 'Wait without your phone', 'In a queue or waiting room today, stay off your phone and just observe.', 'discipline_habits', 5, 2, 'low', 'daytime', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 3, 'checkbox', 'published'),
  ('E096', 'Des plages pour internet', 'Aujourd''hui, ne consulte internet et tes messages que pendant des plages prévues à l''avance.', 'Scheduled internet time', 'Today, check the internet and your messages only during time slots planned in advance.', 'discipline_habits', 5, 3, 'medium', 'daytime', 'action', array['entrepreneur', 'employee']::public.persona[], array['procrastination']::public.blocker[], 7, 'checkbox', 'published'),
  ('E097', 'Le rituel de fin de journée', 'En fin de journée de travail, note les tâches en cours, prépare la liste de demain et dis « terminé » pour clôturer.', 'Shutdown ritual', 'At the end of the workday, note unfinished tasks, prepare tomorrow''s list and say “done” to close.', 'discipline_habits', 5, 1, 'low', 'evening', 'action', array['entrepreneur', 'employee', 'career_changer']::public.persona[], array['organisation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E098', 'Le défi des 30 jours', 'Choisis une habitude et engage-toi à la faire 30 jours de suite, en version minimale si besoin.', 'The 30-day challenge', 'Choose one habit and commit to doing it 30 days in a row, in its minimal version if needed.', 'discipline_habits', 2, 2, 'low', 'any', 'action', '{}'::public.persona[], array['motivation']::public.blocker[], 30, 'checkbox', 'published'),
  ('E099', 'Une seule habitude à la fois', 'Choisis la seule nouvelle habitude sur laquelle tu te concentres les deux prochaines semaines.', 'One habit at a time', 'Choose the single new habit you will focus on for the next two weeks.', 'discipline_habits', 5, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 14, 'free_text', 'published'),
  ('E100', 'Le score de la journée', 'Note ta discipline du jour de 1 à 10 et écris ce qui te ferait gagner un point demain.', 'Score your day', 'Rate today''s discipline from 1 to 10 and write what would earn you one more point tomorrow.', 'discipline_habits', 2, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 1, 'numeric', 'published'),
  ('E101', 'Les petites tâches tout de suite', 'Ce matin, fais immédiatement chaque petite tâche de moins de deux minutes qui se présente.', 'Small tasks right away', 'This morning, do every small task that takes under two minutes as soon as it comes up.', 'discipline_habits', 15, 1, 'low', 'morning', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 7, 'checkbox', 'published'),
  ('E102', 'L''audit du temps d''écran', 'Relève ton temps d''écran d''hier et fixe-toi une limite pour aujourd''hui.', 'Screen time audit', 'Check yesterday''s screen time and set yourself a limit for today.', 'discipline_habits', 2, 1, 'low', 'morning', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 7, 'numeric', 'published'),
  ('E103', 'Ma semaine idéale', 'Dessine ta semaine idéale : blocs de travail, sport, famille, apprentissage.', 'My ideal week', 'Sketch your ideal week: work blocks, exercise, family, learning.', 'discipline_habits', 30, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E104', 'Le plan des jours chargés', 'Définis la version minimale de chacune de tes habitudes pour tes journées les plus chargées.', 'The busy-day plan', 'Define the minimal version of each of your habits for your busiest days.', 'discipline_habits', 10, 1, 'low', 'any', 'writing', '{}'::public.persona[], array['motivation', 'organisation']::public.blocker[], 60, 'free_text', 'published'),
