  ('E169', 'Les forces de mon équipe', 'Note la principale force de chaque membre de ton équipe ou de ton réseau proche et comment mieux l''utiliser.', 'My team''s strengths', 'Note the main strength of each member of your team or close network and how to make better use of it.', 'business_career', 15, 2, 'medium', 'any', 'reflection', array['entrepreneur', 'employee']::public.persona[], '{}'::public.blocker[], 90, 'free_text', 'published'),
  ('E170', 'Réfléchir à plusieurs', 'Organise 20 minutes de réflexion collective sur un problème avec une ou deux personnes.', 'Think it through together', 'Set up 20 minutes of group thinking on a problem with one or two people.', 'business_career', 30, 3, 'medium', 'daytime', 'social', array['entrepreneur', 'employee']::public.persona[], '{}'::public.blocker[], 30, 'free_text', 'published'),
  ('E171', 'Cartographier ses compétences', 'Liste tes compétences et note pour chacune sa rareté et sa valeur sur le marché, de 1 à 5.', 'Map your skills', 'List your skills and rate each one''s rarity and market value from 1 to 5.', 'business_career', 15, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 180, 'free_text', 'published'),
  ('E172', 'Lire son marché', 'Lis cinq offres d''emploi ou de mission qui t''intéressent et note les compétences qui reviennent le plus.', 'Read your market', 'Read five job or contract listings that interest you and note the skills that come up most.', 'business_career', 15, 1, 'low', 'any', 'learning', array['employee', 'career_changer']::public.persona[], '{}'::public.blocker[], 90, 'free_text', 'published'),
  ('E173', 'La pratique délibérée', 'Travaille 25 minutes sur un point faible précis d''une compétence, avec un retour immédiat (exercice corrigé, enregistrement, mentor).', 'Deliberate practice', 'Work for 25 minutes on one specific weak point of a skill, with immediate feedback (marked exercise, recording, mentor).', 'business_career', 30, 4, 'high', 'any', 'learning', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E174', 'Expliquer pour apprendre', 'Explique par écrit, avec des mots simples, une notion que tu es en train d''apprendre.', 'Explain to learn', 'Explain in writing, in simple words, a concept you are currently learning.', 'business_career', 10, 2, 'medium', 'any', 'learning', '{}'::public.persona[], '{}'::public.blocker[], 7, 'free_text', 'published'),
