  ('E176', 'Ajuster ses blocs', 'En fin de journée, compare ce qui était prévu et ce qui a été fait, et ajuste le plan de demain.', 'Adjust your blocks', 'At the end of the day, compare what was planned with what got done, and adjust tomorrow''s plan.', 'business_career', 5, 1, 'low', 'evening', 'reflection', array['entrepreneur', 'employee', 'career_changer']::public.persona[], array['organisation']::public.blocker[], 1, 'free_text', 'published'),
