  ('E179', 'Mes domaines de résultats clés', 'Liste les cinq à sept domaines dont dépendent tes résultats professionnels et note-toi de 1 à 10 dans chacun.', 'My key result areas', 'List the five to seven areas your work results depend on and rate yourself from 1 to 10 in each.', 'business_career', 15, 2, 'medium', 'any', 'reflection', array['entrepreneur', 'employee']::public.persona[], array['organisation']::public.blocker[], 90, 'numeric', 'published'),
