  ('E181', 'Préparer son poste de travail', 'Avant de commencer, rassemble tout ce dont tu as besoin et ferme ce qui est inutile.', 'Prepare your workspace', 'Before you start, gather everything you need and close everything you don''t.', 'business_career', 5, 1, 'low', 'morning', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E182', 'Préparer un rendez-vous important', 'Note l''objectif du rendez-vous, ce que tu sais de ton interlocuteur et trois questions à lui poser.', 'Prepare an important meeting', 'Write the meeting''s goal, what you know about the other person and three questions to ask them.', 'business_career', 15, 2, 'medium', 'any', 'writing', array['entrepreneur', 'employee']::public.persona[], array['fear']::public.blocker[], 3, 'free_text', 'published'),
