  ('E185', 'Se fixer des échéances', 'Donne une date limite à chaque tâche importante de ta liste qui n''en a pas.', 'Set deadlines', 'Give a deadline to every important task on your list that doesn''t have one.', 'business_career', 10, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['procrastination']::public.blocker[], 14, 'numeric', 'published'),
