  ('E187', 'Mettre à jour son profil professionnel', 'Actualise ton profil (LinkedIn, site, CV) avec tes trois dernières réalisations chiffrées.', 'Update your professional profile', 'Update your profile (LinkedIn, website, CV) with your three latest achievements, with figures.', 'business_career', 30, 2, 'medium', 'any', 'action', '{}'::public.persona[], array['confidence']::public.blocker[], 90, 'checkbox', 'published'),
  ('E188', 'Partager son expertise', 'Partage un conseil utile tiré de ton expérience dans une publication ou un message.', 'Share your expertise', 'Share one useful tip from your experience in a post or a message.', 'business_career', 15, 3, 'medium', 'any', 'action', array['entrepreneur', 'career_changer']::public.persona[], array['fear', 'confidence']::public.blocker[], 7, 'checkbox', 'published'),
