  ('E190', 'Écouter un client', 'Appelle ou rencontre un client pour comprendre ses problèmes, sans chercher à lui vendre quoi que ce soit.', 'Listen to a customer', 'Call or meet a customer to understand their problems, without trying to sell them anything.', 'business_career', 30, 3, 'medium', 'daytime', 'social', array['entrepreneur']::public.persona[], array['fear']::public.blocker[], 30, 'free_text', 'published'),
