  ('E192', 'Calculer la valeur de son heure', 'Calcule ce que vaut réellement une heure de ton temps et liste les tâches qui valent moins, à déléguer ou supprimer.', 'Work out what your hour is worth', 'Work out what one hour of your time is really worth and list the tasks worth less, to delegate or drop.', 'business_career', 15, 2, 'medium', 'any', 'reflection', array['entrepreneur']::public.persona[], array['finances', 'organisation']::public.blocker[], 90, 'numeric', 'published'),
