  ('E195', 'Ma déclaration d''objectif', 'Rédige une déclaration à la première personne : ce que tu veux, pour quand, et ce que tu fais pour l''obtenir.', 'My goal statement', 'Write a first-person statement: what you want, by when, and what you are doing to get it.', 'mindset_beliefs', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 90, 'free_text', 'published'),
