  ('E197', 'Observer ses pensées', 'Trois fois aujourd''hui, note la pensée qui t''occupe à ce moment-là et si elle t''aide ou te freine.', 'Watch your thoughts', 'Three times today, note the thought on your mind at that moment and whether it helps or holds you back.', 'mindset_beliefs', 5, 1, 'low', 'daytime', 'reflection', '{}'::public.persona[], array['confidence']::public.blocker[], 7, 'free_text', 'published'),
