  ('E200', 'Trois gratitudes précises', 'Note trois choses précises pour lesquelles tu es reconnaissant aujourd''hui, et pourquoi.', 'Three specific gratitudes', 'Write three specific things you are grateful for today, and why.', 'mindset_beliefs', 2, 1, 'low', 'evening', 'writing', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'free_text', 'published'),
