  ('E202', 'La gratitude pour un obstacle', 'Choisis une difficulté actuelle et note ce qu''elle t''apprend ou te permet.', 'Gratitude for an obstacle', 'Pick a current difficulty and note what it teaches you or makes possible.', 'mindset_beliefs', 5, 2, 'low', 'evening', 'reflection', '{}'::public.persona[], array['confidence']::public.blocker[], 14, 'free_text', 'published'),
  ('E203', 'Nommer sa peur', 'Écris la peur qui te freine le plus face à ton objectif, ce qui pourrait réellement arriver, et ce que tu ferais dans ce cas.', 'Name your fear', 'Write the fear that holds you back most from your goal, what could actually happen, and what you would do then.', 'mindset_beliefs', 10, 3, 'medium', 'any', 'writing', '{}'::public.persona[], array['fear']::public.blocker[], 30, 'free_text', 'published'),
