  ('E214', 'Féliciter quelqu''un', 'Félicite sincèrement aujourd''hui une personne pour une réussite.', 'Congratulate someone', 'Sincerely congratulate someone on a success today.', 'mindset_beliefs', 2, 1, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E215', 'Écrire ses affirmations d''action', 'Écris trois affirmations au présent qui décrivent ce que tu fais, pas seulement ce que tu veux (par exemple « je contacte deux prospects par jour »).', 'Write action affirmations', 'Write three present-tense affirmations that describe what you do, not just what you want (for example “I contact two prospects a day”).', 'mindset_beliefs', 10, 1, 'low', 'morning', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 30, 'free_text', 'published'),
