  ('E217', 'Ma part de responsabilité', 'Pour une situation qui te frustre, écris ce qui dépend de toi et une action que tu peux faire.', 'My share of responsibility', 'For a situation that frustrates you, write what depends on you and one action you can take.', 'mindset_beliefs', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['confidence']::public.blocker[], 14, 'free_text', 'published'),
