  ('E223', 'Respirer avant de répondre', 'Avant de répondre à un message qui t''agace, prends trois respirations lentes.', 'Breathe before replying', 'Before replying to a message that annoys you, take three slow breaths.', 'mindset_beliefs', 2, 1, 'low', 'daytime', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E224', 'Noter son intuition', 'Avant une décision, note ce que ton intuition te dit, puis vérifie plus tard si elle avait raison.', 'Record your gut feeling', 'Before a decision, note what your gut tells you, then check later whether it was right.', 'mindset_beliefs', 2, 1, 'low', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 7, 'free_text', 'published'),
