  ('E227', 'La marche sans téléphone', 'Marche dix minutes sans téléphone ni écouteurs, en observant ce qui t''entoure.', 'The phone-free walk', 'Walk for ten minutes without your phone or earphones, noticing what''s around you.', 'mindset_beliefs', 10, 1, 'low', 'any', 'action', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
