  ('E229', 'Ce que la journée m''a appris', 'Note une leçon de ta journée et comment tu l''appliqueras.', 'What today taught me', 'Note one lesson from your day and how you will apply it.', 'mindset_beliefs', 5, 1, 'low', 'evening', 'writing', '{}'::public.persona[], '{}'::public.blocker[], 1, 'free_text', 'published'),
  ('E230', 'Relire son journal', 'Relis tes notes du mois et repère une tendance : ce qui revient, ce qui progresse.', 'Reread your journal', 'Reread this month''s notes and spot a pattern: what keeps coming back, what is improving.', 'mindset_beliefs', 15, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 30, 'free_text', 'published'),
  ('E231', 'Le bocal des victoires', 'Note chaque victoire, même petite, et relis la liste quand ta confiance baisse.', 'The wins jar', 'Write down every win, however small, and reread the list when your confidence dips.', 'mindset_beliefs', 2, 1, 'low', 'evening', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 1, 'free_text', 'published'),
  ('E232', 'Se parler comme à un ami', 'Écris ce que tu dirais à un ami dans ta situation, puis applique-le à toi-même.', 'Talk to yourself like a friend', 'Write what you would tell a friend in your situation, then apply it to yourself.', 'mindset_beliefs', 5, 2, 'low', 'evening', 'writing', '{}'::public.persona[], array['confidence']::public.blocker[], 14, 'free_text', 'published'),
  ('E233', 'Mon modèle de réussite', 'Choisis une personne inspirante et note trois habitudes ou croyances que tu veux adopter.', 'My role model', 'Choose an inspiring person and note three habits or beliefs you want to adopt.', 'mindset_beliefs', 10, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['motivation']::public.blocker[], 90, 'free_text', 'published'),
  ('E234', 'Visualiser une journée réussie', 'Le matin, visualise une minute ta journée bien menée, puis note la première action à faire.', 'Picture a successful day', 'In the morning, picture your day going well for one minute, then note the first action to take.', 'mindset_beliefs', 2, 1, 'low', 'morning', 'visualisation', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'free_text', 'published'),
  ('E235', 'Former son mastermind', 'Liste trois à cinq personnes ambitieuses avec qui tu pourrais échanger régulièrement sur vos objectifs.', 'Form your mastermind', 'List three to five ambitious people you could meet regularly to talk about your goals.', 'relationships_network', 15, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 180, 'free_text', 'published'),
  ('E236', 'Inviter au mastermind', 'Propose à une ou deux de ces personnes une première rencontre de 45 minutes.', 'Invite to your mastermind', 'Suggest a first 45-minute meeting to one or two of these people.', 'relationships_network', 10, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['fear']::public.blocker[], 90, 'checkbox', 'published'),
  ('E237', 'Préparer sa session de mastermind', 'Prépare ton point : avancée depuis la dernière fois, blocage actuel, aide demandée.', 'Prepare your mastermind session', 'Prepare your update: progress since last time, current blocker, help you''re asking for.', 'relationships_network', 10, 2, 'medium', 'any', 'writing', '{}'::public.persona[], '{}'::public.blocker[], 14, 'free_text', 'published'),
  ('E238', 'Une journée sans critique', 'Aujourd''hui, ne critique personne ; quand l''envie vient, cherche plutôt ce qui explique le comportement de l''autre.', 'A day without criticism', 'Criticise no one today; when the urge comes, look instead for what explains the other person''s behaviour.', 'relationships_network', 2, 2, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 14, 'checkbox', 'published'),
  ('E239', 'Un compliment précis', 'Fais à quelqu''un un compliment sincère et précis sur ce qu''il a fait, pas sur ce qu''il est.', 'A specific compliment', 'Give someone a sincere, specific compliment on something they did, not on who they are.', 'relationships_network', 2, 1, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E240', 'Remercier publiquement', 'Remercie publiquement un collègue, un client ou un partenaire pour une contribution précise.', 'Thank someone publicly', 'Publicly thank a colleague, client or partner for a specific contribution.', 'relationships_network', 5, 2, 'low', 'daytime', 'social', array['entrepreneur', 'employee']::public.persona[], array['fear']::public.blocker[], 14, 'checkbox', 'published'),
  ('E241', 'Se mettre à sa place', 'Avant une demande importante, écris ce que l''autre veut, ce qu''il craint et ce qu''il gagne à accepter.', 'Put yourself in their shoes', 'Before an important request, write what the other person wants, fears and gains by saying yes.', 'relationships_network', 10, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 7, 'free_text', 'published'),
  ('E242', 'Réécrire un message', 'Reprends un message que tu vas envoyer et reformule-le en partant de l''intérêt de ton interlocuteur.', 'Rewrite a message', 'Take a message you''re about to send and rewrite it starting from the other person''s interest.', 'relationships_network', 5, 2, 'medium', 'daytime', 'writing', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E243', 'Trois questions sur l''autre', 'Dans une conversation aujourd''hui, pose au moins trois questions sur ton interlocuteur avant de parler de toi.', 'Three questions about them', 'In a conversation today, ask at least three questions about the other person before talking about yourself.', 'relationships_network', 5, 1, 'low', 'daytime', 'social', '{}'::public.persona[], array['confidence']::public.blocker[], 3, 'checkbox', 'published'),
  ('E244', 'Reprendre des nouvelles', 'Envoie un message à une personne perdue de vue pour prendre de ses nouvelles, sans rien lui demander.', 'Check in on someone', 'Message someone you''ve lost touch with to see how they are, without asking for anything.', 'relationships_network', 5, 1, 'low', 'any', 'social', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E245', 'Retenir les prénoms', 'Retiens et réutilise le prénom de chaque nouvelle personne rencontrée aujourd''hui, et note-les le soir.', 'Remember names', 'Remember and use the name of everyone new you meet today, and write them down in the evening.', 'relationships_network', 2, 2, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 7, 'numeric', 'published'),
  ('E246', 'Écouter sans interrompre', 'Dans une conversation, écoute jusqu''au bout sans interrompre ni préparer ta réponse, puis reformule ce que tu as compris.', 'Listen without interrupting', 'In a conversation, listen to the end without interrupting or preparing your reply, then sum up what you understood.', 'relationships_network', 10, 2, 'medium', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E247', 'Chercher le terrain d''entente', 'Avant un désaccord, liste les points sur lesquels vous êtes d''accord et commence par eux.', 'Find common ground', 'Before a disagreement, list the points you agree on and start with those.', 'relationships_network', 5, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['fear']::public.blocker[], 7, 'free_text', 'published'),
  ('E248', 'Désamorcer une tension', 'Dans un échange tendu, dis « je comprends ton point de vue, explique-moi » plutôt que de contre-argumenter.', 'Defuse tension', 'In a tense exchange, say “I see your point, tell me more” instead of arguing back.', 'relationships_network', 2, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E249', 'Reconnaître une erreur', 'Reconnais aujourd''hui une erreur auprès de la personne concernée, sans te justifier.', 'Own a mistake', 'Admit a mistake today to the person concerned, without justifying yourself.', 'relationships_network', 5, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['fear', 'confidence']::public.blocker[], 14, 'checkbox', 'published'),
  ('E250', 'La reformulation', 'Avant de donner ton avis aujourd''hui, résume ce que l''autre vient de dire et vérifie que c''est juste.', 'Reflect back', 'Before giving your opinion today, sum up what the other person just said and check you got it right.', 'relationships_network', 2, 2, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E251', 'Faire un dépôt de confiance', 'Fais aujourd''hui un petit geste de confiance pour un proche : tenir une promesse, rendre service, une attention.', 'Make a trust deposit', 'Make a small gesture of trust for someone close today: keep a promise, help out, a thoughtful touch.', 'relationships_network', 5, 1, 'low', 'any', 'social', '{}'::public.persona[], '{}'::public.blocker[], 1, 'free_text', 'published'),
  ('E252', 'Mes relations clés', 'Liste tes dix relations les plus importantes, professionnelles et personnelles, et note la dernière fois que tu as investi dans chacune.', 'My key relationships', 'List your ten most important relationships, work and personal, and note the last time you invested in each.', 'relationships_network', 15, 2, 'medium', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'free_text', 'published'),
  ('E253', 'Tenir une petite promesse', 'Fais aujourd''hui une petite promesse et tiens-la dans la journée.', 'Keep a small promise', 'Make a small promise today and keep it the same day.', 'relationships_network', 5, 1, 'low', 'daytime', 'action', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E254', 'Mon entourage en revue', 'Liste les cinq personnes avec qui tu passes le plus de temps et note si elles te tirent vers le haut ou vers le bas.', 'Review your circle', 'List the five people you spend the most time with and note whether they lift you up or pull you down.', 'relationships_network', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 90, 'free_text', 'published'),
  ('E255', 'Rejoindre un groupe', 'Trouve un groupe, un club ou une communauté liée à ton objectif et inscris-toi ou participe à une rencontre.', 'Join a group', 'Find a group, club or community linked to your goal and sign up or attend a meetup.', 'relationships_network', 15, 3, 'medium', 'any', 'social', '{}'::public.persona[], array['fear']::public.blocker[], 90, 'checkbox', 'published'),
  ('E256', 'Un café inspirant', 'Propose un café ou un déjeuner à une personne qui a un temps d''avance sur toi dans ton domaine.', 'An inspiring coffee', 'Invite someone who is a step ahead of you in your field for coffee or lunch.', 'relationships_network', 10, 3, 'medium', 'daytime', 'social', '{}'::public.persona[], array['fear', 'confidence']::public.blocker[], 30, 'checkbox', 'published'),
  ('E257', 'Le premier sourire', 'Aujourd''hui, salue et souris en premier à chaque personne que tu croises au travail ou dans ton quartier.', 'Smile first', 'Today, be the first to greet and smile at everyone you pass at work or in your neighbourhood.', 'relationships_network', 2, 1, 'low', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E258', 'Demander conseil', 'Demande l''avis de quelqu''un sur un sujet où il est compétent, et dis-lui ce que tu en as retenu.', 'Ask for advice', 'Ask someone''s opinion on a topic they know well, and tell them what you took from it.', 'relationships_network', 10, 2, 'medium', 'daytime', 'social', '{}'::public.persona[], '{}'::public.blocker[], 14, 'checkbox', 'published'),
  ('E259', 'Mettre en relation', 'Présente l''une à l''autre deux personnes de ton réseau qui gagneraient à se connaître.', 'Make an introduction', 'Introduce two people in your network who would benefit from knowing each other.', 'relationships_network', 10, 2, 'medium', 'any', 'social', array['entrepreneur', 'employee']::public.persona[], '{}'::public.blocker[], 14, 'checkbox', 'published'),
  ('E260', 'Un nouveau contact par semaine', 'Prends contact cette semaine avec une nouvelle personne utile à ton projet.', 'One new contact a week', 'Reach out this week to one new person who is useful to your project.', 'relationships_network', 10, 3, 'medium', 'any', 'social', array['entrepreneur', 'career_changer']::public.persona[], array['fear']::public.blocker[], 7, 'checkbox', 'published'),
  ('E261', 'Préparer un événement réseau', 'Avant un événement, fixe-toi un objectif (nombre de rencontres, une personne précise) et prépare ta présentation.', 'Prepare a networking event', 'Before an event, set a goal (number of conversations, one specific person) and prepare your introduction.', 'relationships_network', 10, 2, 'medium', 'any', 'reflection', array['entrepreneur', 'career_changer']::public.persona[], array['fear']::public.blocker[], 7, 'free_text', 'published'),
  ('E262', 'Relancer après une rencontre', 'Envoie un message de suivi aux personnes rencontrées récemment, avec un élément personnel de votre échange.', 'Follow up after meeting', 'Send a follow-up message to people you met recently, mentioning something personal from your conversation.', 'relationships_network', 10, 1, 'low', 'any', 'social', '{}'::public.persona[], array['procrastination']::public.blocker[], 7, 'numeric', 'published'),
  ('E263', 'Du temps de qualité', 'Passe 30 minutes avec un proche sans téléphone, pleinement présent.', 'Quality time', 'Spend 30 minutes with someone close, phone away, fully present.', 'relationships_network', 30, 1, 'low', 'evening', 'social', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E264', 'Le bilan des quatre dimensions', 'Note-toi de 1 à 10 sur le corps, l''esprit, les relations et le sens, puis choisis une action pour la note la plus basse.', 'The four-dimension check', 'Rate yourself from 1 to 10 on body, mind, relationships and purpose, then choose one action for the lowest score.', 'energy_health', 10, 1, 'low', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 30, 'numeric', 'published'),
  ('E265', 'Un temps pour se ressourcer', 'Bloque dans ta semaine un moment pour une activité qui te ressource vraiment.', 'Time to recharge', 'Block time this week for an activity that truly recharges you.', 'energy_health', 5, 1, 'low', 'any', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'checkbox', 'published'),
  ('E266', 'Dix minutes de mouvement', 'Bouge dix minutes aujourd''hui : marche rapide, étirements ou quelques exercices au poids du corps.', 'Ten minutes of movement', 'Move for ten minutes today: brisk walk, stretching or a few bodyweight exercises.', 'energy_health', 10, 2, 'medium', 'any', 'action', '{}'::public.persona[], array['motivation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E267', 'Le réveil musculaire', 'Au réveil, fais deux minutes de mouvements simples pour activer ton corps.', 'Morning wake-up moves', 'When you wake up, do two minutes of simple movements to get your body going.', 'energy_health', 2, 1, 'low', 'morning', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E268', 'Escaliers et marche', 'Prends les escaliers aujourd''hui et fais un trajet à pied plutôt qu''en transport.', 'Stairs and walking', 'Take the stairs today and make one trip on foot instead of by transport.', 'energy_health', 10, 1, 'low', 'daytime', 'action', '{}'::public.persona[], '{}'::public.blocker[], 3, 'checkbox', 'published'),
  ('E269', 'Une réunion en marchant', 'Transforme un appel ou une réunion en réunion en marchant.', 'A walking meeting', 'Turn a call or meeting into a walking meeting.', 'energy_health', 30, 1, 'low', 'daytime', 'action', array['entrepreneur', 'employee']::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E270', 'Une heure de coucher fixe', 'Choisis une heure de coucher pour la semaine et programme un rappel 30 minutes avant.', 'A set bedtime', 'Choose a bedtime for the week and set a reminder 30 minutes before.', 'energy_health', 2, 1, 'low', 'evening', 'action', '{}'::public.persona[], array['organisation']::public.blocker[], 7, 'checkbox', 'published'),
  ('E271', 'Le soir sans écran', 'Coupe les écrans 30 minutes avant de dormir et remplace-les par une lecture ou un moment calme.', 'Screen-free evening', 'Switch off screens 30 minutes before sleep and replace them with reading or a quiet moment.', 'energy_health', 30, 2, 'low', 'evening', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E272', 'Noter son sommeil', 'Note ton heure de coucher, ton heure de lever et ta forme au réveil, de 1 à 5.', 'Log your sleep', 'Note your bedtime, wake-up time and how rested you feel on waking, from 1 to 5.', 'energy_health', 2, 1, 'low', 'morning', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 1, 'numeric', 'published'),
  ('E273', 'Ma courbe d''énergie', 'Pendant trois jours, note ton niveau d''énergie toutes les deux heures pour repérer tes pics.', 'My energy curve', 'For three days, note your energy level every two hours to find your peaks.', 'energy_health', 2, 1, 'low', 'daytime', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 90, 'numeric', 'published'),
  ('E274', 'La tâche difficile au bon moment', 'Planifie ta tâche la plus exigeante de demain sur ton créneau de pleine forme.', 'Hard task, right time', 'Schedule tomorrow''s most demanding task during your peak-energy slot.', 'energy_health', 2, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], array['organisation']::public.blocker[], 1, 'checkbox', 'published'),
  ('E275', 'Ce qui me vide', 'Liste les activités ou situations qui te vident de ton énergie et une façon de réduire chacune.', 'What drains me', 'List the activities or situations that drain your energy and one way to reduce each.', 'energy_health', 10, 2, 'medium', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 60, 'free_text', 'published'),
  ('E276', 'La pause active', 'Toutes les 90 minutes de travail, fais une pause de 5 minutes loin de l''écran.', 'The active break', 'Every 90 minutes of work, take a 5-minute break away from the screen.', 'energy_health', 5, 1, 'low', 'daytime', 'action', array['entrepreneur', 'employee', 'career_changer']::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E277', 'Le travail par séquences', 'Enchaîne au moins deux séquences de 25 minutes de travail suivies de 5 minutes de pause.', 'Work in sprints', 'Do at least two rounds of 25 minutes of work followed by a 5-minute break.', 'energy_health', 30, 2, 'medium', 'daytime', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 1, 'checkbox', 'published'),
  ('E278', 'Une vraie pause déjeuner', 'Prends ta pause déjeuner loin de ton poste de travail, sans écran.', 'A real lunch break', 'Take your lunch break away from your desk, without screens.', 'energy_health', 30, 1, 'low', 'daytime', 'action', array['employee', 'entrepreneur']::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E279', 'Dix pages par jour', 'Lis dix pages d''un livre utile à ton objectif.', 'Ten pages a day', 'Read ten pages of a book that helps with your goal.', 'energy_health', 15, 1, 'low', 'any', 'learning', '{}'::public.persona[], '{}'::public.blocker[], 1, 'numeric', 'published'),
  ('E280', 'Ma liste de lecture', 'Choisis les trois prochains livres à lire en lien avec ton objectif.', 'My reading list', 'Choose the next three books to read that relate to your goal.', 'energy_health', 10, 1, 'low', 'any', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 90, 'free_text', 'published'),
  ('E281', 'Une idée par chapitre', 'Après chaque chapitre lu, note l''idée principale et une façon de l''appliquer.', 'One idea per chapter', 'After each chapter you read, note the main idea and one way to apply it.', 'energy_health', 5, 1, 'low', 'any', 'writing', '{}'::public.persona[], '{}'::public.blocker[], 3, 'free_text', 'published'),
  ('E282', 'Désactiver les notifications', 'Désactive les notifications de toutes les applications qui ne sont pas essentielles.', 'Turn off notifications', 'Turn off notifications for every app that isn''t essential.', 'energy_health', 10, 1, 'low', 'any', 'action', '{}'::public.persona[], array['procrastination']::public.blocker[], 90, 'checkbox', 'published'),
  ('E283', 'Le téléphone hors de la chambre', 'Ce soir, laisse ton téléphone en dehors de ta chambre.', 'Phone out of the bedroom', 'Tonight, leave your phone outside your bedroom.', 'energy_health', 2, 2, 'low', 'evening', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E284', 'Une demi-journée déconnectée', 'Passe une demi-journée de ton week-end sans réseaux sociaux ni e-mails.', 'A half-day offline', 'Spend half a day of your weekend without social media or email.', 'energy_health', 30, 3, 'low', 'any', 'action', '{}'::public.persona[], '{}'::public.blocker[], 7, 'checkbox', 'published'),
  ('E285', 'Un verre d''eau au réveil', 'Bois un grand verre d''eau dès le réveil, avant le café.', 'A glass of water on waking', 'Drink a large glass of water as soon as you wake up, before coffee.', 'energy_health', 2, 1, 'low', 'morning', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E286', 'Dix minutes à la lumière du jour', 'Passe au moins dix minutes dehors à la lumière du jour, de préférence le matin.', 'Ten minutes of daylight', 'Spend at least ten minutes outside in daylight, ideally in the morning.', 'energy_health', 10, 1, 'low', 'morning', 'action', '{}'::public.persona[], '{}'::public.blocker[], 1, 'checkbox', 'published'),
  ('E287', 'Le bilan énergie de la semaine', 'Regarde tes niveaux d''énergie de la semaine et note ce qui les a fait monter ou baisser.', 'Weekly energy review', 'Look at your energy levels this week and note what raised or lowered them.', 'energy_health', 10, 1, 'low', 'evening', 'reflection', '{}'::public.persona[], '{}'::public.blocker[], 7, 'free_text', 'published');
