insert into public.habit_templates (id, title_fr, description_fr, title_en, description_en, domain, frequency, time_of_day, default_cue_fr, default_cue_en, minimal_version_fr, minimal_version_en, personas, status) values
  ('H01', 'Lire son objectif', 'Relire son objectif principal à voix haute.', 'Read your goal', 'Read your main goal aloud.', 'clarity_goals', 'daily', 'morning', 'Après m''être brossé les dents le matin', 'After brushing my teeth in the morning', 'Lire seulement la première phrase', 'Read just the first sentence', '{}'::public.persona[], 'published'),
  ('H02', 'Choisir sa grenouille', 'Désigner chaque soir la tâche la plus importante du lendemain.', 'Pick your frog', 'Each evening, name tomorrow''s most important task.', 'clarity_goals', 'daily', 'evening', 'Après avoir fermé l''ordinateur', 'After closing my laptop', 'Noter un seul mot', 'Write a single word', '{}'::public.persona[], 'published'),
  ('H03', 'Trois priorités du jour', 'Choisir trois priorités au maximum pour la journée.', 'Three daily priorities', 'Choose no more than three priorities for the day.', 'clarity_goals', 'daily', 'morning', 'Avec le premier café', 'With my first coffee', 'Une seule priorité', 'Just one priority', '{}'::public.persona[], 'published'),
  ('H04', 'Revue hebdomadaire', 'Faire le bilan de la semaine et fixer trois priorités pour la suivante.', 'Weekly review', 'Review the week and set three priorities for the next one.', 'clarity_goals', 'weekly', 'evening', 'Le dimanche après le dîner', 'Sunday after dinner', 'Cinq minutes : trois priorités de la semaine', 'Five minutes: three priorities for the week', '{}'::public.persona[], 'published'),
  ('H05', 'Plan si-alors du jour', 'Écrire un plan « si… alors… » pour l''obstacle le plus probable de la journée.', 'Daily if-then plan', 'Write an “if… then…” plan for the day''s most likely obstacle.', 'clarity_goals', 'daily', 'morning', 'En ouvrant l''application le matin', 'When I open the app in the morning', 'Un seul plan, en une ligne', 'One plan, one line', '{}'::public.persona[], 'published'),
  ('H06', 'Travail profond', 'Un bloc de travail concentré, notifications coupées.', 'Deep work', 'A block of focused work with notifications off.', 'discipline_habits', 'weekdays', 'morning', 'Après le café, en arrivant au bureau', 'After coffee, when I get to my desk', 'Dix minutes concentrées', 'Ten focused minutes', array['entrepreneur', 'employee', 'career_changer']::public.persona[], 'published'),
  ('H07', 'Routine matinale', 'Suivre sa routine du matin.', 'Morning routine', 'Follow your morning routine.', 'discipline_habits', 'daily', 'morning', 'Au réveil', 'When I wake up', 'Deux minutes : un verre d''eau et son objectif', 'Two minutes: a glass of water and my goal', '{}'::public.persona[], 'published'),
  ('H08', 'Rituel de fin de journée', 'Clôturer sa journée de travail et préparer le lendemain.', 'Shutdown ritual', 'Close the workday and prepare for tomorrow.', 'discipline_habits', 'weekdays', 'evening', 'À l''heure de fin de journée prévue', 'At my planned finishing time', 'Noter la première tâche de demain', 'Write down tomorrow''s first task', array['entrepreneur', 'employee', 'career_changer']::public.persona[], 'published'),
  ('H09', 'Pas d''écran au réveil', 'Ne pas consulter e-mails ni réseaux sociaux la première heure.', 'No screens on waking', 'No email or social media during the first hour.', 'discipline_habits', 'daily', 'morning', 'En éteignant le réveil', 'When I turn off my alarm', 'Quinze minutes sans écran', 'Fifteen screen-free minutes', '{}'::public.persona[], 'published'),
  ('H10', 'Suivre ses habitudes', 'Cocher ses habitudes du jour dans l''application.', 'Track your habits', 'Tick off today''s habits in the app.', 'discipline_habits', 'daily', 'evening', 'Après le dîner', 'After dinner', 'Cocher une seule habitude', 'Tick just one habit', '{}'::public.persona[], 'published'),
  ('H11', 'Préparer la veille', 'Préparer le soir ce qu''il faut pour les habitudes du lendemain.', 'Prepare the night before', 'In the evening, set out what you need for tomorrow''s habits.', 'discipline_habits', 'daily', 'evening', 'Avant de me brosser les dents le soir', 'Before brushing my teeth at night', 'Préparer un seul objet', 'Prepare one item', '{}'::public.persona[], 'published'),
  ('H12', 'Faire son lit', 'Commencer la journée par une petite tâche accomplie.', 'Make your bed', 'Start the day with one small task done.', 'discipline_habits', 'daily', 'morning', 'En sortant du lit', 'As I get out of bed', 'Remonter la couette', 'Pull up the duvet', '{}'::public.persona[], 'published'),
  ('H13', 'Se payer en premier', 'Mettre de côté une part de ses revenus dès leur réception.', 'Pay yourself first', 'Set aside part of your income as soon as it arrives.', 'money_wealth', 'monthly', 'any', 'Le jour où je reçois mes revenus', 'The day my income arrives', 'Mettre de côté 1 %', 'Set aside 1%', '{}'::public.persona[], 'published'),
  ('H14', 'Noter ses dépenses', 'Noter les dépenses de la journée.', 'Log your spending', 'Write down the day''s spending.', 'money_wealth', 'daily', 'evening', 'Après le dîner', 'After dinner', 'Noter la plus grosse dépense', 'Log the biggest expense', array['financial_beginner']::public.persona[], 'published'),
  ('H15', 'La règle des 48 heures', 'Attendre 48 heures avant tout achat non prévu.', 'The 48-hour rule', 'Wait 48 hours before any unplanned purchase.', 'money_wealth', 'occasional', 'daytime', 'Devant un achat non prévu', 'When I''m about to make an unplanned purchase', 'Attendre jusqu''au lendemain', 'Wait until the next day', '{}'::public.persona[], 'published'),
  ('H16', 'Un mot de finance', 'Apprendre un terme financier par jour.', 'One finance word', 'Learn one financial term a day.', 'money_wealth', 'daily', 'morning', 'Pendant le café du matin', 'During my morning coffee', 'Lire une seule définition', 'Read one definition', array['financial_beginner']::public.persona[], 'published'),
  ('H17', 'Revue financière mensuelle', 'Faire le point sur l''épargne, le budget et le patrimoine net.', 'Monthly money review', 'Review savings, budget and net worth.', 'money_wealth', 'monthly', 'evening', 'Le premier dimanche du mois', 'The first Sunday of the month', 'Regarder seulement le solde et l''épargne', 'Check only the balance and savings', '{}'::public.persona[], 'published'),
  ('H18', 'Alimenter sa réserve', 'Verser une somme sur son épargne de précaution.', 'Top up your reserve', 'Put money into your emergency fund.', 'money_wealth', 'weekly', 'any', 'Le lundi matin', 'Monday morning', 'Verser 5 €', 'Put in €5', '{}'::public.persona[], 'published'),
  ('H19', 'Dix idées', 'Noter dix idées liées à son activité ou à son objectif.', 'Ten ideas', 'Write ten ideas related to your business or goal.', 'business_career', 'daily', 'morning', 'Avec le café du matin', 'With my morning coffee', 'Trois idées', 'Three ideas', array['entrepreneur', 'career_changer']::public.persona[], 'published'),
  ('H20', 'Une prise de contact', 'Contacter un prospect, un client ou un partenaire.', 'One outreach', 'Reach out to a prospect, client or partner.', 'business_career', 'weekdays', 'daytime', 'Après la pause déjeuner', 'After my lunch break', 'Un message court', 'One short message', array['entrepreneur']::public.persona[], 'published'),
  ('H21', 'Apprendre une compétence', 'Travailler la compétence qui fera progresser ses revenus.', 'Build a skill', 'Work on the skill that will grow your income.', 'business_career', 'daily', 'evening', 'Après le dîner', 'After dinner', 'Dix minutes', 'Ten minutes', '{}'::public.persona[], 'published'),
  ('H22', 'Planifier sa journée en blocs', 'Découper la journée de demain en blocs de travail.', 'Time-block your day', 'Split tomorrow into work blocks.', 'business_career', 'weekdays', 'evening', 'Avant de fermer l''ordinateur', 'Before closing my laptop', 'Placer seulement le bloc de la grenouille', 'Place only the frog''s block', array['entrepreneur', 'employee', 'career_changer']::public.persona[], 'published'),
  ('H23', 'Journal des réussites', 'Noter ses réalisations professionnelles de la semaine.', 'Wins journal', 'Write down the week''s work achievements.', 'business_career', 'weekly', 'evening', 'Le vendredi en fin de journée', 'Friday at the end of the day', 'Une réussite', 'One win', '{}'::public.persona[], 'published'),
  ('H24', 'Partager son expertise', 'Publier un conseil utile tiré de son expérience.', 'Share your expertise', 'Post one useful tip from your experience.', 'business_career', 'weekly', 'morning', 'Le mardi matin', 'Tuesday morning', 'Un commentaire utile sous une publication', 'One useful comment on a post', array['entrepreneur', 'career_changer']::public.persona[], 'published'),
  ('H25', 'Trois gratitudes', 'Noter trois choses précises pour lesquelles on est reconnaissant.', 'Three gratitudes', 'Write three specific things you are grateful for.', 'mindset_beliefs', 'daily', 'evening', 'Au coucher', 'At bedtime', 'Une gratitude', 'One gratitude', '{}'::public.persona[], 'published'),
  ('H26', 'Lire sa déclaration', 'Lire sa déclaration d''objectif avec conviction.', 'Read your statement', 'Read your goal statement with conviction.', 'mindset_beliefs', 'daily', 'morning', 'Après le petit-déjeuner', 'After breakfast', 'Une phrase', 'One sentence', '{}'::public.persona[], 'published'),
  ('H27', 'Cinq minutes de silence', 'S''asseoir en silence en se concentrant sur sa respiration.', 'Five minutes of silence', 'Sit in silence, focusing on your breathing.', 'mindset_beliefs', 'daily', 'morning', 'Au réveil, avant le téléphone', 'On waking, before my phone', 'Trois respirations lentes', 'Three slow breaths', '{}'::public.persona[], 'published'),
  ('H28', 'Écriture libre', 'Écrire sans s''arrêter ce qui passe par la tête.', 'Free writing', 'Write non-stop whatever comes to mind.', 'mindset_beliefs', 'daily', 'morning', 'Avec le café du matin', 'With my morning coffee', 'Trois lignes', 'Three lines', '{}'::public.persona[], 'published'),
  ('H29', 'La leçon du jour', 'Noter une leçon de la journée.', 'Lesson of the day', 'Write down one lesson from the day.', 'mindset_beliefs', 'daily', 'evening', 'Après le check-in du soir', 'After the evening check-in', 'Un mot', 'One word', '{}'::public.persona[], 'published'),
  ('H30', 'Une dose d''inconfort', 'Faire une petite chose qui sort de sa zone de confort.', 'A dose of discomfort', 'Do one small thing outside your comfort zone.', 'mindset_beliefs', 'weekly', 'daytime', 'En planifiant la semaine', 'When I plan my week', 'Poser une question que j''aurais gardée pour moi', 'Ask a question I would have kept to myself', '{}'::public.persona[], 'published'),
  ('H31', 'Un compliment par jour', 'Faire un compliment sincère et précis.', 'One compliment a day', 'Give a sincere, specific compliment.', 'relationships_network', 'daily', 'daytime', 'À la première conversation de la journée', 'At my first conversation of the day', 'Un merci précis', 'A specific thank-you', '{}'::public.persona[], 'published'),
  ('H32', 'Prendre des nouvelles', 'Envoyer un message à une personne perdue de vue.', 'Check in on someone', 'Message someone you''ve lost touch with.', 'relationships_network', 'weekly', 'any', 'Le dimanche après-midi', 'Sunday afternoon', 'Un message d''une ligne', 'A one-line message', '{}'::public.persona[], 'published'),
  ('H33', 'Écouter avant de parler', 'Poser une question sur l''autre avant de parler de soi.', 'Listen before speaking', 'Ask about the other person before talking about yourself.', 'relationships_network', 'daily', 'daytime', 'Au début de chaque réunion ou conversation', 'At the start of each meeting or conversation', 'Une question', 'One question', '{}'::public.persona[], 'published'),
  ('H34', 'Session de mastermind', 'Retrouver son groupe pour faire le point sur ses objectifs.', 'Mastermind session', 'Meet your group to review your goals.', 'relationships_network', 'biweekly', 'any', 'À date fixe dans l''agenda', 'A fixed date in my calendar', 'Quinze minutes en visio', 'Fifteen minutes on video', '{}'::public.persona[], 'published'),
  ('H35', 'Temps de qualité', 'Passer un moment avec un proche, sans téléphone.', 'Quality time', 'Spend time with someone close, phone away.', 'relationships_network', 'daily', 'evening', 'Après le dîner', 'After dinner', 'Dix minutes', 'Ten minutes', '{}'::public.persona[], 'published'),
  ('H36', 'Dix minutes de mouvement', 'Bouger dix minutes : marche, étirements, exercices simples.', 'Ten minutes of movement', 'Move for ten minutes: walking, stretching, simple exercises.', 'energy_health', 'daily', 'daytime', 'À la pause de midi', 'At my lunch break', 'Deux minutes d''étirements', 'Two minutes of stretching', '{}'::public.persona[], 'published'),
  ('H37', 'Heure de coucher fixe', 'Se coucher à heure fixe.', 'Set bedtime', 'Go to bed at a set time.', 'energy_health', 'daily', 'evening', 'Rappel 30 minutes avant l''heure choisie', 'Reminder 30 minutes before my chosen time', 'Se coucher 15 minutes plus tôt que d''habitude', 'Go to bed 15 minutes earlier than usual', '{}'::public.persona[], 'published'),
  ('H38', 'Dix pages par jour', 'Lire dix pages d''un livre utile à son objectif.', 'Ten pages a day', 'Read ten pages of a book that helps your goal.', 'energy_health', 'daily', 'evening', 'Au coucher', 'At bedtime', 'Une page', 'One page', '{}'::public.persona[], 'published'),
  ('H39', 'Pause active', 'Faire une pause loin de l''écran toutes les 90 minutes.', 'Active break', 'Take a break away from the screen every 90 minutes.', 'energy_health', 'weekdays', 'daytime', 'Toutes les 90 minutes de travail', 'Every 90 minutes of work', 'Se lever une minute', 'Stand up for one minute', array['entrepreneur', 'employee', 'career_changer']::public.persona[], 'published'),
